-- 213 — اصلاح نص قانون سوق رأس المال 95/1992 (137 مادة) من نسخة الهيئة العامة للرقابة المالية المحدَّثة (PDF)
-- ----------------------------------------------------------------------------
-- المشكلة: النص المخزَّن من استخراج PDF فيه (1) حرفا "ؤ" و"ج" محذوفان من نحو 65 موضعاً (مثل: "ت ثر" بدل "تؤثر"، "م سسة" بدل "مؤسسة"،
--          "نموذ" بدل "نموذج"، "الاندما" بدل "الاندماج"، و"( )" بدل "(ج)" فى بنود المواد)، (2) تمطيط حروف (ننن...) داخل الكلمات فى المادتين
--          3 و14 مكرر 18 (مثل "لسنننننة" بدل "لسنة"، "يشننننترط" بدل "يشترط")، (3) عناوين الأبواب والفصول مدسوسة فى آخر المادة السابقة،
--          (4) أسطر مكسورة عند حدود الصفحة بدل الفقرات، (5) عنوان الموقع الجغرافى للباب الأول والخامس مشوّه ("األول"/"اخلامس").
-- الإصلاح: أُعيد بناء النص من أحرف الملف نفسه بإحداثياتها (لا من طبقة النص المكسورة)، ثم قورن بالنص المخزَّن مادةً مادة: الفروق كلها محصورة
--          فى الأنواع الأربعة المذكورة (ؤ وج المستعادة، التمطيط المحذوف، العناوين، الفقرات)؛ كل الحروف والأرقام الأخرى مطابقة تماماً.
--          وقورن بقراءة OCR مستقلة لصفحات الملف الـ42؛ وفحصت بصرياً مواضع الاشتباه. أخطاء المطبعة الموجودة فى الملف الرسمى نفسه
--          (مثل "التنفيض" و"تجربها" و"نقع مؤثم" و"يتشرط") بقيت كما وردت دون تدخل.
-- الضمان: كل مادة تُحدَّث فقط إذا كان md5 نصها الحالى أحد النصين المقيسين (قبل/بعد 208) أو كانت "بصمتها الحرفية" (الحروف والأرقام بعد حذف
--          ا أ إ آ ل ه والعلامات) مطابقة لبصمة النص المتوقع؛ غير ذلك: تحذير وتخطٍّ دون كتابة. النص القديم يُحفظ فى migration_213_backup.
--          نسخ article_versions المطابقة تُحدَّث معها. embeddings لا تُمس. قابلة لإعادة التشغيل.
-- ============================================================================

CREATE TABLE IF NOT EXISTS migration_213_backup (
  article_id uuid NOT NULL,
  version_id uuid,
  old_body   text NOT NULL,
  saved_at   timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_213_backup_art ON migration_213_backup (article_id) WHERE version_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_213_backup_ver ON migration_213_backup (version_id) WHERE version_id IS NOT NULL;

DO $m213$
DECLARE
  r record;
  v_law uuid; v_aid uuid; v_cur text;
  v_ok_art int := 0; v_ok_ver int := 0; v_done int := 0; v_skip int := 0; v_n int;
BEGIN
  SELECT l.id INTO v_law FROM laws l
   WHERE l.country_code = 'EG' AND l.kind = 'law' AND l.law_no = 95 AND l.law_year = 1992;
  IF v_law IS NULL THEN
    RAISE WARNING '[213] القانون 95/1992 غير موجود — تخطّى';
    RETURN;
  END IF;

  -- تصحيح عنوان الموقع المشوَّه فى الباب الأول والباب الخامس (فقط حين يطابق القيمة المشوَّهة المعروفة)
  UPDATE articles SET hierarchical_location = 'الباب الأول'
   WHERE law_id = v_law AND hierarchical_location = 'الباب األول';
  UPDATE articles SET hierarchical_location = 'الباب الخامس'
   WHERE law_id = v_law AND hierarchical_location = 'الباب اخلامس';

  FOR r IN SELECT * FROM (VALUES
    (1, -1, ARRAY['1430b204d5df05d57106f69ca9231088']::text[], ARRAY['9c01c19047301ebd00bede556e053169']::text[], '71b48c4172581dc959f8e11fd3ceff52', replace($b$يعمل بأحكام القانون المرافق في شأن تنظيم سوق رأس المال.
وتسري أحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981 فيما لم يرد به نص خاص في هذا القانون.$b$, E'\n', E'\r\n')),
    (2, -1, ARRAY['6d4096566522110792b5dc7feb7f74f3']::text[], ARRAY['a7d734d9dcd7a3bf2c0a7d136a70f76c']::text[], '34871c3a2232df4c0417a4e44fc9e757', replace($b$يقصد في تطبيق أحكام القانون المرافق بالهيئة أو الجهة الإدارية أينما وردتا في هذا القانون ولائحته التنفيذية أو القانون رقم 159 لسنة 1981 ولائحته التنفيذية الهيئة العامة للرقابة المالية ويقصد برئيس الهيئة رئيس مجلس إدارة الهيئة العامة للرقابة المالية ويقصد بالوزير المختص رئيس مجلس الوزراء.
*معدلة بموجب القانون رقم 10 لسنة 2009 النص قبل التعديل: يقصد في تطبيق أحكام القانون المرافق بالهيئة أو الجهة الإدارية أينما وردتا في هذا القانون ولائحته التنفيذية أو القانون رقم 159 لسنة 1981 ولائحته التنفيذية الهيئة العامة لسوق المال، ويقصد برئيس الهيئة رئيس مجلس إدارة الهيئة العامة لسوق المال ويقصد بالوزير وزير الاقتصاد والتجارة الخارجية.$b$, E'\n', E'\r\n')),
    (3, -1, ARRAY['bda4a06bf65a427f559f19ad65a4f9bf']::text[], ARRAY['44493c8f63ead7707fac27a519af8152']::text[], '071b788359fed1f1f17672163006001c', replace($b$يصدر الوزير المختص بناء على عرض رئيس مجلس إدارة الهيئة العامة للرقابة المالية اللائحة التنفيذية للقانون المرافق خلال ثلاثة أشهر من تاريخ العمل به.
وإلى أن تصدر اللائحة التنفيذية والقرارات المنفذة لهذا القانون يستمر العمل بالأحكام والقواعد والنظم القائمة في تاريخ العمل به فيما لا يتعارض مع أحكامه.
*معدلة بموجب القانون رقم 10 لسنة 2009 النص قبل التعديل: يصدر وزير الاقتصاد والتجارة الخارجية بناء على عرض رئيس مجلس إدارة الهيئة العامة لسوق المال اللائحة التنفيذية للقانون المرافق خلال ثلاثة أشهر من تاريخ العمل به.
وإلى أن تصدر اللائحة التنفيذية والقرارات المنفذة لهذا القانون يستمر العمل بالأحكام والقواعد والنظم القائمة في تاريخ العمل به فيما لا يتعارض مع أحكامه.$b$, E'\n', E'\r\n')),
    (4, -1, ARRAY['2abe8b65daae36e6b6c6bedaa8d2825d']::text[], ARRAY['8fc595d21d205cc8a514b51164af1038']::text[], '5b3d0a729912700ae56e37e0cda4e76c', replace($b$دون إخلال بحكم المادة (25) من القانون المرافق، يلغى القانون رقم 161 لسنة 1957 باللائحة العامة لبورصات الأوراق المالية، ويلغى كل حكم مخالف لأحكام القانون المرافق.$b$, E'\n', E'\r\n')),
    (5, -1, ARRAY['d1046ea1db04e02a5816382abc291e29']::text[], ARRAY['7e26fa2d10803a654dd2f1fcbf44add7']::text[], '1036fe9fd4e249bbabb7378e88bdf165', replace($b$ينشر هذا القانون في الجريدة الرسمية، ويعمل به من اليوم التالي لتاريخ نشره.
يبصم هذا القانون بخاتم الدولة، وينفذ كقانون من قوانينها.
صدر برئاسة الجمهورية في 21 ذي الحجة سنة 1412 هـ
(الموافق 22 يونيه سنة 1992 م ).$b$, E'\n', E'\r\n')),
    (1, 0, ARRAY['5afa087291d93835602bbb2848c941a4']::text[], ARRAY['9c715a288be6734adac48c4777e672e9']::text[], 'a8f0a4f5f29bed6334b8afc8e11251e3', replace($b$يقسم رأسمال شركة المساهمة وحصة الشركاء غير المتضامنين في شركات التوصية بالأسهم إلى أسهم أسمية متساوية القيمة.
ويحدد نظام الشركة قيمة السهم الاسمية بحيث لا تقل عن عشرة قروش ولا تزيد على ألف جنيه.
ويكون السهم غير قابل للتجزئة.
ويجوز إصدار أسهم جديدة عند زيادة رأس المال بقيمة مغايرة لقيمة الأسهم من الإصدارات السابقة، وتكون للأسهم الجديدة ذات حقوق والتزامات أسهم الإصدارات السابقة.
وتبين اللائحة التنفيذية ما تتضمنه شهادات الأسهم من بيانات، وكيفية استبدال الشهادات المفقودة أو التالفة وما يتبع بالنسبة لهذه الشهادات عند تعديل نظام الشركة.
*تلغى الفقرة الأخيرة من المادة (1) من قانون سوق رأس المال بموجب قانون رقم 17 لسنة 2018
نص الفقرة قبل الإلغاء: كما تبين اللائحة التنفيذية الأحكام الخاصة بطرح الأسهم في اكتتاب عام.
*الفقرة الأولى معدلة بموجب قانون رقم 17 لسنة 2018 نص الفقرة قبل التعديل: يقسم رأس مال شركة المساهمة وحصة الشركاء غير المتضامنين في شركات التوصية بالأسهم إلى أسهم اسمية متساوية القيمة، ومع ذلك يجوز للشركة إصدار أسهم لحاملها في الحدود ووفقا للشروط والأوضاع والإجراءات التي تبينها اللائحة التنفيذية. ولا يكون لحاملي هذه الأسهم الحق في التصويت في الجمعيات العامة.
*الفقرة الثانية معدلة بموجب القانون رقم 123 لسنة 2008 النص قبل التعديل: يقسم رأس مال شركة المساهمة وحصة الشركاء غير المتضامنين في شركات التوصية بالأسهم إلى أسهم اسمية متساوية القيمة، ومع ذلك يجوز للشركة إصدار أسهم لحاملها في الحدود ووفقا للشروط والأوضاع والإجراءات التي تبينها اللائحة التنفيذية. ولا يكون لحاملي هذه الأسهم الحق في التصويت في الجمعيات العامة.
ويحدد نظام الشركة قيمة السهم الاسمية بحيث لا تقل عن خمسة جنيهات ولا تزيد على ألف جنيه ولا يسري هذا الحكم على الشركات القائمة وقت العمل بهذا القانون.
ويكون السهم غير قابل للتجزئة.
ويجوز إصدار أسهم جديدة عند زيادة رأس المال بقيمة مغايرة لقيمة الأسهم من الإصدارات السابقة، وتكون للأسهم الجديدة ذات حقوق والتزامات أسهم الإصدارات السابقة.
وتبين اللائحة التنفيذية ما تتضمنه شهادات الأسهم من بيانات، وكيفية استبدال الشهادات المفقودة أو التالفة وما يتبع بالنسبة لهذه الشهادات عند تعديل نظام الشركة.
كما تبين اللائحة التنفيذية الأحكام الخاصة بطرح الأسهم في اكتتاب عام.$b$, E'\n', E'\r\n')),
    (2, 0, ARRAY['773b6c083b74da2f0ebb8372ba9f3569']::text[], ARRAY['8386d130cf663b30e972e52070b45c36']::text[], 'db70c4ff35ceba86687a7dd47e608e40', replace($b$يلتزم كل شخص اعتباري يرغب في إصدار أوراق مالية أن يخطر الهيئة بذلك، فإذا لم تعترض الهيئة خلال سبعة أيام عمل من تاريخ إخطارها يتم السير في إجراءات الإصدار،
وتحدد اللائحة التنفيذية لهذا القانون بيانات الإخطار والمستندات التي ترفق به.
*معدلة بموجب القانون رقم 123 لسنة 2008 النص قبل التعديل: على كل شركة ترغب في إصدار أوراق مالية أن تخطر الهيئة بذلك، فإذا لم تعترض الهيئة خلال ثلاثة أسابيع من تاريخ الإخطار كان للشركة السير في إجراءات الإصدار، وذلك دون إخلال بأي حكم آخر في هذا القانون.
وتحدد اللائحة التنفيذية بيانات الإخطار والمستندات التي ترفق به.$b$, E'\n', E'\r\n')),
    (3, 0, ARRAY['512afda6908618574c5050f14e74a31f']::text[], ARRAY['ed91cc46f3312f001dd1aa65caad164a']::text[], 'a7ef7e3d0f097eccbab002407a39f24f', replace($b$ملغاة
*ملغاة بموجب القانون رقم 13 لسنة 2004 النص قبل الإلغاء: يشترط لإصدار أسهم مقابل حصة عينية أو بمناسبة الاندماج أن تكون قيمة هذه الأسهم مطابقة لقيمة الحصة أو الحقوق المندمجة كما حددتها لجنة التقييم المختصة وذلك دون إخلال بحق أصحاب الشأن في التظلم لدى لجنة التظلمات المنصوص عليها في الباب الخامس من هذا القانون من التحديد الذي قررته لجنة التقييم وفقا للأوضاع والإجراءات التي تبينها اللائحة التنفيذية. ومع ذلك يجوز لمقدم الحصة العينية أن يؤدي الفرق نقدا كما يجوز له أن ينسحب. وفي جميع الأحوال لا يجوز إصدار هذه الأسهم إلا بعد فوات ميعاد التظلم أو البت فيه.$b$, E'\n', E'\r\n')),
    (4, 0, ARRAY['3db3bad91726ff06382bd23e5c375c2c']::text[], ARRAY['c6ea7776bd846965f770529802c7a831']::text[], '2e59fc675a39b1e9b9de7e726cbd40f9', replace($b$لا يجوز لأى شخص اعتباري مصري أو غير مصري، أيا كانت طبيعته أو النظام القانوني الخاضع له ، طرح أوراق أو أدوات مالية في اكتتاب عام للجمهور إلا بناء على نشرة اكتتاب معتمدة من الهيئة ، وعلى النماذج التي تعدها الهيئة ، ووفقا للشروط والإجراءات التي تحددها اللائحة التنفيذية لهذا القانون ، ويجب نشر ملخص نشرة الاكتتاب أو نشرة الطرح أو تقرير الإفصاح بغرض الطرح وفقا لوسائل النشر التي يحددها مجلس إدارة الهيئة. ومع عدم الإخلال بحكم الفقرة السابقة ، يصدر مجلس إدارة الهيئة الضوابط التي يجب الالتزام بها عند طرح أي أوراق أو أدوات مالية في اكتتاب عام أو طرح عام أو طرح خاص ، وذلك بحسب نوع الورقة أو الأداة المالية.
*معدلة بموجب قانون رقم 17 لسنة 2018 نص المادة قبل التعديل: لا يجوز لأي شخص اعتباري مصري أو غير مصري أيا كانت طبيعته وأيا كان النظام القانوني الخاضع له طرح أوراق مالية في اكتتاب عام للجمهور إلا بناء على نشرة اكتتاب معتمدة من الهيئة يتم نشرها في صحيفتين مصريتين يوميتين واسعتي الانتشار، إحداهما على الأقل باللغة العربية، وذلك كله وفقا للأوضاع والشروط التي تضعها اللائحة التنفيذية لهذا القانون.
ويجب أن تحرر نشرة الاكتتاب وفقا لنموذج تعده الهيئة.
*معدلة بموجب القانون رقم 123 لسنة 2008 النص قبل التعديل : لا يجوز طرح أوراق مالية لأية شركة بما في ذلك شركات قطاع الأعمال العام وشركات القطاع العام في اكتتاب عام للجمهور إلا بناء على نشرة اكتتاب معتمدة من الهيئة يتم نشرها في صحيفتين يوميتين صباحيتين واسعتي الانتشار، إحداهما على الأقل باللغة العربية. ويجب أن تحرر نشرة الاكتتاب وفقا للنماذج التي تعدها الهيئة.$b$, E'\n', E'\r\n')),
    (4, 1, ARRAY['407127a8ebf91b50fc352cecc72ebb4c']::text[], ARRAY['c1a18624f4ef0d6c79029ac899343923']::text[], '37c569e6c4a18e01f9672eeeb61732a8', replace($b$في تطبيق أحكام هذا القانون والقرارات الصادرة تنفيذا له ، يقصد بالعبارات التالية المعنى المبين قرين كل منها: الاكتتاب العام : عرض أوراق مالية أو أدوات مالية على أشخاص طبيعيين أو اعتباريين غير محددين سلفا عند إصدار هذه الأوراق أو الأدوات.
الطرح العام : عرض أوراق مالية أو أدوات مالية مصدرة على أشخاص طبيعيين أو اعتباريين غير محددين سلفا. الطرح الخاص : عرض أوراق مالية أو أدوات مالية على أشخاص طبيعيين أو اعتباريين تتوافر فيهم شروط معينة سواء عند إصدار هذه الأوراق أو الأدوات أو بعد ذلك.
الأدوات المالية : وثائق تغاير الأوراق المالية ، وتكون قابلة للقيد والتداول ببورصات الأوراق المالية.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (5, 0, ARRAY['400bd355dec52ae779414459af10bbb3']::text[], ARRAY['8d8d76a467677cc630b12d087efc5c2b']::text[], '29f24a845654af2ffa152525d6c3ab9c', replace($b$يجب أن تتضمن نشرة الاكتتاب في أسهم الشركة عند تأسيسها الإفصاح عن البيانات الآتية:
(أ) غرض الشركة ومدتها.
(ب) رأس مال الشركة المصدر والمدفوع.
(ج) مواصفات الأسهم المطروحة ومميزاتها وشروط طرحها.
(د) أسماء المؤسسين ومقدار مساهمة كل منهم وبيان الحصص العينية إن وجدت.
(هـ) خطة الشركة في استخدام الأموال المتحصلة من الاكتتاب في الأسهم المطروحة وتوقعاتها بالنسبة لنتائج استخدام الأموال.
(و) أماكن الحصول على نشرة الاكتتاب المعتمدة من الهيئة.
(ز) أية بيانات تحددها اللائحة التنفيذية.
ويجب أن تتضمن نشرات الاكتتاب الأخرى بالإضافة إلى البيانات المشار إليها في الفقرة السابقة الإفصاح عن البيانات الآتية:
(أ) سابقة أعمال الشركة.
(ب) أسماء أعضاء مجلس الإدارة والمديرين المسئولين بها وخبراتهم.
(ج) أسماء حاملي الأسهم الاسمية الذين يملك كل منهم أكثر من 5% من أسهم الشركة ونسبة ما يملكه كل منهم. (د) موجز للقوائم والبيانات المالية المعتمدة من مراقبي الحسابات عن السنوات الثلاثة السابقة أو عن المدة من تاريخ تأسيس الشركة أيهما أقل والمعدة طبقا لقواعد الإفصاح التي تبينها اللائحة التنفيذية والنماذج التي تضعها الهيئة.$b$, E'\n', E'\r\n')),
    (6, 0, ARRAY['7f00ea67ef08c149fe11bd2d53a04c17']::text[], ARRAY['780e15835927fd25ca246a02c0ee53d0']::text[], 'a6f942313e6e3fd3a74b5f4041c9e664', replace($b$على كل شركة طرحت أوراقا مالية لها في اكتتاب عام أن تقدم على مسئوليتها إلى الهيئة تقارير نصف سنوية عن نشاطها ونتائج أعمالها على أن تتضمن هذه التقارير البيانات التي تفصح عن المركز المالي الصحيح لها.
وتعد الميزانية وغيرها من القوائم المالية للشركة طبقا للمعايير المحاسبية ولقواعد المراجعة التي تحددها أو تحيل إليها اللائحة التنفيذية.
وتخطر الهيئة بالميزانية وبالقوائم المالية وتقريري مجلس الإدارة ومراقب الحسابات عنها قبل شهر من التاريخ المحدد لانعقاد الجمعية العامة.
وللهيئة فحص الوثائق المشار إليها في الفقرات السابقة أو تكليف جهة متخصصة بهذا الفحص، وتبلغ الهيئة الشركة بملاحظاتها، وتطلب إعادة النظر في هذه الوثائق بما يتفق ونتائج الفحص، فإذا لم تستجب الشركة لذلك التزمت بنفقات نشر الهيئة لملاحظاتها والتعديلات التي طلبتها، ويتم النشر على الوجه المبين بالفقرة التالية. ويجب على الشركة نشر ملخص للقوائم المالية ، والإيضاحات المتممة لها ، وتقرير مراقب الحسابات بوسائل النشر طبقا للقواعد والضوابط التي يضعها مجلس إدارة الهيئة.
كما يجب على كل شركة تواجه ظروفا جوهرية تؤثر على نشاطها أو في مركزها المالي أن تفصح عن ذلك فورا بوسائل النشر طبقا للقواعد والضوابط التي يضعها مجلس إدارة الهيئة.
*الفقرتين الخامسة والسادسة معدلة بموجب قانون رقم 17 لسنة 2018 نص المادة قبل التعديل: على كل شركة طرحت أوراقا مالية لها في اكتتاب عام أن تقدم على مسئوليتها إلى الهيئة تقارير نصف سنوية عن نشاطها ونتائج أعمالها على أن تتضمن هذه التقارير البيانات التي تفصح عن المركز المالي الصحيح لها.
وتعد الميزانية وغيرها من القوائم المالية للشركة طبقا للمعايير المحاسبية ولقواعد المراجعة التي تحددها أو تحيل إليها اللائحة التنفيذية.
وتخطر الهيئة بالميزانية وبالقوائم المالية وتقريري مجلس الإدارة ومراقب الحسابات عنها قبل شهر من التاريخ المحدد لانعقاد الجمعية العامة.
وللهيئة فحص الوثائق المشار إليها في الفقرات السابقة أو تكليف جهة متخصصة بهذا الفحص، وتبلغ الهيئة الشركة بملاحظاتها، وتطلب إعادة النظر في هذه الوثائق بما يتفق ونتائج الفحص، فإذا لم تستجب الشركة لذلك التزمت بنفقات نشر الهيئة لملاحظاتها والتعديلات التي طلبتها، ويتم النشر على الوجه المبين بالفقرة التالية. ويجب على الشركة نشر ملخص واف للتقارير النصف سنوية والقوائم المالية السنوية في صحيفتين يوميتين صباحيتين واسعتي الانتشار إحداهما على الأقل باللغة العربية.
كما يجب على كل شركة تواجه ظروفا جوهرية طارئة تؤثر في نشاطها أو في مركزها المالي أن تفصح عن ذلك فورا وأن تنشر عنه ملخصا وافيا في صحيفتين يوميتين صباحيتين واسعتي الانتشار إحداهما على الأقل باللغة العربية.$b$, E'\n', E'\r\n')),
    (7, 0, ARRAY['17f69f9122bd092f23e71cd86b65cae1']::text[], ARRAY['8a0a630bde48d1dbf8675444fbdcc16e']::text[], '35d3aa5a0663b95a07433514113d4664', replace($b$على الشركة ومراقبي حساباتها موافاة الهيئة بما تطلبه من بيانات ووثائق للتحقق من صحة البيانات الواردة بنشرات الاكتتاب والتقارير الدورية والبيانات والقوائم المالية للشركة.$b$, E'\n', E'\r\n')),
    (8, 0, ARRAY['9a6419ea3dc0ecfa7f676c6d45e636f1']::text[], ARRAY['7f002b63f0cb135ab9c53a5ab04f27c7']::text[], 'fd0305d9e2b9f770213de8ee8a2398eb', replace($b$تنظم اللائحة التنفيذية لهذا القانون أحكام عروض الشراء وعمليات الاستحواذ على الأسهم وغيرها من الأوراق المالية القابلة للتحول إلى أسهم في الشركات المقيدة لها أوراق مالية في بورصات الأوراق المالية ، أو التي طرحت أوراقا مالية في اكتتاب عام ، أو من خلال طرح عام ولو لم تكن مقيدة في بورصات الأوراق المالية ، وعلى الأخص ما يأتي:
1. ضوابط ومتطلبات حماية حقوق الاقلية من المساهمين.
2. الحالات التي يتعين فيها تقديم عروض إجبارية لشراء الأوراق المالية.
3. الإجراءات التنفيذية ومتطلبات الإفصاح الخاصة بعروض الشراء أو عمليات الاستحواذ.
4. الحالات التي يتعين فيها الإفصاح المسبق أو اللاحق لعمليات شراء أو بيع الأوراق المالية ببورصات الأوراق المالية.
*معدلة بموجب قانون رقم 17 لسنة 2018 نص المادة قبل التعديل: على كل من يرغب في عقد عملية يترتب عليها تجاوز ما يملكه 10% من الأسهم الاسمية في رأس مال إحدى الشركات التي طرحت أسهما لها في اكتتاب عام أن يخطر الشركة قبل عقد العملية بأسبوعين على الأقل.
وعلى الشركة خلال أسبوع من تاريخ إخطارها بذلك أن تبلغ به كل مساهم يملك 1% على الأقل من رأس مال الشركة.
ويترتب على مخالفة أحكام الفقرة الأولى إلغاء العملية دون إخلال بمساءلة المتسبب عن هذه المخالفة.
وتسري أحكام الفقرات السابقة في حالة عقد عملية يترتب عليها تجاوز ما يملكه أحد أعضاء مجلس إدارة الشركة أو أحد العاملين بها من أسهم اسميه 5% من رأس مال الشركة.
ويتعين اتخاذ الإجراءات المشار إليها من هذه المادة قبل عقد كل عملية فيما يجاوز النسبتين المنصوص عليهما في الفقرتين الأولى والرابعة.
وتبين اللائحة التنفيذية أحكام عقد العمليات وإجراءات الإخطار والإبلاغ.
*استدراك - تصحيح خطأ لسنة 1992 - بشأن تصحيح خطأ بالعدد 25 مكرر من الجريدة الرسمية الصادر بتاريخ 22 يونيه سنة 1992 لقانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992.$b$, E'\n', E'\r\n')),
    (9, 0, ARRAY['7454973e7ef544d5eb8e940eabc2f1fd']::text[], ARRAY['12f803c586f9056f8a121411cb5a4fbb']::text[], '40e492564de66352179a418c8ff4caf9', replace($b$لا يجوز للمساهم أن يمثل في اجتماع الجمعية العامة للشركة عن طريق الوكالة عددا من الأصوات يجاوز الحد الذي تعينه اللائحة التنفيذية.$b$, E'\n', E'\r\n')),
    (10, 0, ARRAY['288fac305cce7757f1d5627eec0ea6f3']::text[], ARRAY['72fe446bd62857823ba649ea979ca3cf']::text[], '9dc9ca30b5c6b444fa698c637c9e3cef', replace($b$لمجلس إدارة الهيئة بناء على أسباب جدية يبديها عدد من المساهمين الذين يملكون 5% على الأقل من أسهم الشركة وبعد التثبيت وقف قرارات الجمعية العامة للشركة التي تصدر لصالح فئة معينة من المساهمين أو للإضرار بهم أو لجلب نفع خاص لأعضاء مجلس الإدارة أو غيرهم.
وعلى أصحاب الشأن عرض طلب إبطال قرارات الجمعية العامة على هيئة التحكيم المنصوص عليها في الباب الخامس من هذا القانون خلال خمسة عشر يوما من تاريخ صدور القرار، فإذا انقضت المدة دون اتخاذ هذا الإجراء اعتبر الوقف كأن لم يكن.*
*قضت المحكمة الدستورية العليا بجلسة 24/ 1/ 2002 في الطعن رقم 55 لسنة 23ق. دستورية بعدم دستورية نص الفقرة الثانية من المادة (10) من قانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992.
النص قبل التعديل :لمجلس إدارة الهيئة بناء على أسباب جدية يبديها عدد من المساهمين الذين يملكون 5% على الأقل من أسهم الشركة وبعد التثبت وقف قرارات الجمعية العامة للشركة التي تصدر لصالح فئة معينة من المساهمين أو للإضرار بهم أو لجلب نفع خاص لأعضاء مجلس الإدارة أو غيرهم.
وعلى أصحاب الشأن عرض طلب إبطال قرارات الجمعية العامة على هيئة التحكيم المنصوص عليها في الباب الخامس من هذا القانون خلال خمسة عشر يوما من تاريخ صدور القرار، فإذا انقضت المدة دون اتخاذ هذا الإجراء اعتبر الوقف كأن لم يكن.$b$, E'\n', E'\r\n')),
    (10, 1, ARRAY['9534f6d520dc21ee37697299e22302ad']::text[], ARRAY['54560a29e201e67c7e2b21554b6628cf']::text[], 'fd152b948d7e85d5346ea3456b420a8a', replace($b$تلتزم الجهة المقيد لها أوراق أو أدوات مالية ببورصات الأوراق المـالية بإتاحة استخدام الأنظمة الإلكترونية التي تكفل لمساهميها حضور اجتماعات الجمعية العامة وإثبات إجراءاتها والتصويت عليها عن بُعد، وذلك كله وفقا للشروط والضوابط والإجراءات التي يصدر بها قرار من مجلس إدارة الهيئة.
*مضافة بموجب قانون رقم 13 لسنة 2022.
*نصت المادة الثانية من قانون رقم 13 لسنة 2022 على:
يلتزم مجلس إدارة الهيئة بإصدار قراره المشار إليه في المـادة (10 مكررا) من هذا القانون خلال مهلة لا تجاوز ستة أشهر من تاريخ العمل بهذا القانون ، وتلتزم الجهات المخاطبة بحكم المـادة المشار إليها بتوفيق أوضاعها وفقا لأحكامها خلال ستة أشهر من تاريخ صدور قرار مجلس إدارة الهيئة المشار إليه أو قبل انعقاد أول جمعية عمومية تالية لصدور القرار أيهما أبعد.$b$, E'\n', E'\r\n')),
    (11, 0, ARRAY['c7cf6f56b6c50f2191f95cc33021cc46']::text[], ARRAY['f12b232a1aec4a6bb901fc1791e375d5']::text[], 'b8a447665de3e3fc0188816e8a341954', replace($b$ينشأ بالهيئة سجل يقيد به مراقبو الحسابات الذين يجوز لهم مراجعة الشركات المقيدة أوراقها ببورصة الأوراق المالية وشركات الاكتتاب العام والشركات العاملة في مجال الأوراق المالية وصناديق الاستثمار المنشاة بالبنوك وشركات التأمين.
ويضع مجلس إدارة الهيئة شروط وأحكام قيد وشطب مراقبي الحسابات في السجل المشار إليه.
*معدلة بموجب القانون رقم 123 لسنة 2008 النص قبل التعديل : مع عدم الإخلال بالإعفاءات الضريبية المقررة لأسهم الشركات المقيدة في سوق الأوراق المالية في تاريخ العمل بهذا القانون، تعفى الأسهم المقيدة في الجداول المبينة بالبند (أ) من المادة 16 من هذا القانون من ضرائب الدمغة النسبية عند الإصدار ومن ضرائب الدمغة النسبية السنوية، كما تعفى الأرباح الموزعة عن هذه الأسهم من الضريبة العامة على الدخل.
وفى حالة بيع الأسهم بقيمة تزيد على ثمن الشراء تخضع الزيادة لضريبة مقدارها 2% من قيمة الزيادة يدفعها البائع وتحصل هذه الضريبة طبقا للقواعد التي يصدر بها قرار من وزير المالية بالاتفاق مع الوزير.$b$, E'\n', E'\r\n')),
    (12, 0, ARRAY['a15792fead8e9341507d569630f8fbc4']::text[], ARRAY['e0fd59735683c88127d14828ed783ded']::text[], '62da865bb8a32d23c55a4de2ed5360db', replace($b$تصدر السندات وصكوك التمويل و الأوراق المالية الأخرى بقرار من الجمعية العامة للشركة، ووفقا للقواعد والإجراءات التي تبينها اللائحة التنفيذية لهذا القانون.
ويجوز بترخيص من الهيئة طرحها في اكتتاب عام.
فإذا كانت السندات وصكوك التمويل والأوراق المالية الأخرى المشار إليها قصيرة الأجل لمدة لا تجاوز سنتين، يجوز أن يكون قرار الإصدار بناء على موافقة مجلس إدارة الشركة بشرط حصوله على تفويض بذلك من الجمعية العامة للشركة، أو موافقة السلطة المختصة في غيرها من الأشخاص الاعتبارية ، ووفقا للقواعد والإجراءات التي يضعها مجلس إدارة الهيئة في شأن إصدارها وطرحها في اكتتاب عام أو خاص.
وفى جميع الأحوال ، يجب أن يتضمن قرار الإصدار العائد الذى يجنيه السند أو الصك أو الورقة المالية ، و أساس حسابه ، دون التقيد بالحدود المنصوص عليها في أي قانون آخر.
*معدلة بموجب قانون رقم 17 لسنة 2018
نص المادة قبل التعديل: يكون إصدار السندات وصكوك التمويل والأوراق المالية الأخرى سواء كانت اسمية أو لحاملها بموافقة الجمعية العامة للشركة ووفقا للقواعد والإجراءات التي تبينها اللائحة التنفيذية، ويجب أن تتضمن موافقة الجمعية العامة العائد الذي يغله السند أو الصك أو الورقة وأساس حسابه دون التقيد بالحدود المنصوص عليها في أي قانون آخر.
ويجب الحصول على ترخيص من الهيئة في حالة طرح السندات وصكوك التمويل والأوراق المالية الأخرى في اكتتاب عام.$b$, E'\n', E'\r\n')),
    (13, 0, ARRAY['d5d93b3b4c20e0a9521b0b5fffa7ea93']::text[], ARRAY['bdd1b279602dcb53497e507730629272']::text[], '51ec51ba0a98fdc56e8f9a896f27f57b', replace($b$يجوز لأصحاب السندات وصكوك التمويل والأوراق المالية الأخرى ذات الإصدار الواحد في الشركة تكوين جماعة يكون غرضها حماية المصالح المشتركة لأعضائها ويكون لها ممثل قانوني من بين أعضائها يتم اختياره وعزله وفقا للشروط والأوضاع المبينة في اللائحة التنفيذية ويشترط ألا تكون له أية علاقة مباشرة أو غير مباشرة بالشركة وألا تكون له مصلحة متعارضة مع مصلحة أعضاء الجماعة.
ويباشر ممثل الجماعة ما تقتضيه حماية المصالح المشتركة لها سواء في مواجهة الشركة أو الغير أو أمام القضاء وذلك في حدود ما تتخذه الجماعة من قرارات في اجتماع صحيح. ويتعين إخطار الهيئة بتشكيل هذه الجماعة واسم ممثلها وصور من قراراتها.
وتحدد اللائحة التنفيذية أوضاع وإجراءات دعوة الجماعة للانعقاد ومن له حق الحضور وكيفية الانعقاد ومكانه والتصويت وعلاقة الجماعة بالشركة والهيئة.$b$, E'\n', E'\r\n')),
    (14, 0, ARRAY['d74162ab15ee41332414d6e00d0c2390']::text[], ARRAY['280510597b0e3ba3fd89ae56c3371918']::text[], 'e398b6e4ea3a1677f762ada63b4c3986', replace($b$ملغاة
*ملغاة بموجب القانون رقم 123 لسنة 2008 النص قبل الإلغاء : مع عدم الإخلال بالإعفاءات الضريبية المقررة للسندات وصكوك التمويل الصادرة من الشركات المقيدة في سوق الأوراق المالية في تاريخ العمل بهذا القانون، تعفى السندات وصكوك التمويل والأوراق المالية الأخرى المماثلة - أيا كانت الجهة المصدرة لها - المقيدة في الجداول المبينة بالبند (أ) من المادة 16 من هذا القانون من ضريبة الدمغة النسبية عند الإصدار ومن ضريبة الدمغة النسبية السنوية، كما يعفى عائد هذه الأوراق من الضريبة على إيرادات رؤوس الأموال المنقولة ومن الضريبة العامة على الدخل.
وفي حالة بيع أي من هذه الأوراق بقيمة تزيد على ثمن الشراء، تخضع الزيادة لضريبة مقدارها 2% من قيمة الزيادة يدفعها البائع وتحصل هذه الضريبة طبقا للقواعد التي يصدر بها قرار من وزير المالية بالاتفاق مع الوزير.$b$, E'\n', E'\r\n')),
    (14, 1, ARRAY['805040f3d0fcc2f9cbc8e1fe11f5f133']::text[], ARRAY['9540aa95d6c08a75fdaa1d243c34742d']::text[], '73e7b63b3b033d5ee00ed8a600074979', replace($b$في تطبيق أحكام هذا القانون والقرارات الصادرة تنفيذا له، يقصد بالكلمات والعبارات التالية ، والمعنى المبين قرين كل منها:
الصكوك : أوراق مالية اسمية متساوية القيمة ، تصدر لمدة محددة لا تزيد على ثلاثين عاما ، تمثل كل منها حصة شائعة في ملكية أصول أو منافع أو حقوق أو مشروع معين أو حقوقه أو التدفقات النقدية له ، وفقا لما تحدده نشرة الاكتتاب العام أو مذكرة المعلومات ، بحسب الأحوال.
المشروع : أي نشاط اقتصادي، مدر للدخل ، وفقا لدراسة جدوى تعد عنه.
التصكيك : عملية مالية يتم من خلالها تملك أصول أو منافع أو مشروع محل التمويل ، أو تملك حقوقه ، و إصدار صكوك مقابلها.
شركة التصكيك : شركة مساهمة مصرية ذات غرض وحيد هو إصدار الصكوك ، يتم تأسيسها والترخيص لها وفقا لأحكام هذا القانون ، وتقوم بتملك الأصول أو المنافع أو الحقوق أو المشروع محل التمويل ، نيابة عن مالكي الصكوك.
الجهة المستفيدة : الشخص الاعتباري المستفيد من التمويل الناتج عن التصكيك، وهو حصيلة الاكتتاب في الصكوك وما تتحول إليها من أموال ، وتشمل الأعيان والمنافع والخدمات و النقود والديون وغيرها من الحقوق المالية.
الجهة المصدرة : شركة التصكيك أو الجهة المستفيدة في حالة عدم وجود شركة تصكيك.
منظم الإصدار : بنك أو شركة أوراق مالية مؤسسة وفق هذا القانون أو أي مؤسسة مالية أخرى ترخص لها الهيئة بإدارة وتنظيم الإصدار والترويج له نيابة عن الجهة المستفيدة والجهة المصدرة.
وكيل السداد : بنك مرخص له من البنك المركزي المصري يعمل وكيلا عن الجهة المصدرة لتنسيق سداد الصكوك و أداء قيمتها في نهاية المدة لمالكيها ، أو إحدى الشركات المرخص لها بمزاولة نشاط الإيداع والقيد المركزي. عقد الإصدار : العقد الذى تصدر على أساسه الصكوك وفقا لأحكام هذا القانون ، وينظم العلاقة بين الجهة المصدرة و الجهة المستفيدة ومنظم الإصدار ومالكي الصكوك ، من حيث مجالات استثمار حصيلة الصكوك ، ومدة هذا الاستثمار ، وعوائد المتوقعة ، وطريقة توزيعها ، وواجبات تلك الجهات ، و آجال الصكوك ، و إمكان تداولها واستردادها.
حق الانتفاع : حق استخدام الأصول التي تصدر الصكوك في مقابلها بما لا ينتج عنه فناء هذه الأصول.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 2, ARRAY['cd6931d77157e45164b0a810d6886364']::text[], ARRAY['1177d06a45cba3ac04b6449aba429751']::text[], '2ff39fbd12e2faf23860ac4375696cf5', replace($b$تصدر الصكوك بموجب عقد إصدار وفقا لإحدى الصيغ الآتية:
( أ ) صكوك المضاربة : تصدر على أساس عقد مضاربة بين مالكي الصكوك والجهة المستفيدة ، وتستخدم حصيلة إصدارها في تمويل نشاط اقتصادي أو مشرع محدد تديره الجهة المستفيدة ، ويمثل الصك حصة شائعة في ملكية موجودات المضاربة ، ويتم توزيع عائد الصكوك من الأرباح التي يحققها النشاط أو المشروع وفق النسبة المحددة في العقد ، ورد قيمتها الإسمية في نهاية أجلها من النشاط أو المشروع.
( ب ) صكوك المرابحة : تصدر على أساس عقد مرابحة ، وتستخدم حصيلة إصدارها لتمويل شراء بضاعة المرابحة لبيعها للواعد بشرائها ، بعد تملكها وقبضها ، ويمثل الصك حصة شائعة في ملكية هذه البضاعة بعد شرائها ، وقبل بيعها وتسليمها لمشتريها ، وفى ثمنها بعد بيعها للواعد بشرائها ، وعائد هذه الصكوك هو الفرق بين ثمن شراء بضاعة المرابحة وثمن بيعها للواعد بشرائها.
( جـ ) صكوك المشاركة : تصدر على أساس عقد مشاركة ، وتستخدم حصيلة إصدارها في تمويل إنشاء مشروع ، أو تطوير مشروع قائم ، أو تمويل نشاط على أساس المشاركة ، ويمثل الصك حصة شائعة في ملكية موجودات المشاركة ، ويستحق مالكو الصكوك حصة من أرباح المشاركة بنسبة ما يملكه كل منهم من صكوك.
(د) صكوك إجارة الموجودات أو الخدمات : تصدر على أساس عقد إجارة موجودات أو خدمات بقصد إعادة تملكها ، وتستخدم حصيلة إصدارها في تمويل شراء الموجودات أو الخدمات لإعادة تأجيرها لمتلقيها بقصد تمليكها لهم بعد سداد ثمنها ، ويمثل الصك حصة شائعة في ملكية الموجودات أو الخدمات ، وعائد هذه الصكوك هو الفرق بين ثمن شراء الموجودات أو الخدمات وثمن بيعها.
(هـ) أي صيغة أخرى لعقود الصكوك تحددها اللائحة التنفيذية لهذا القانون.
وفى جميع الأحوال السابقة ، لا يجوز أن تتضمن صيغة التعاقد نصا بضمان حصة مالك الصك في رأس المال ، أو بضمان عائد مقطوع أو منسوب إلى قيمة الصك ، ويستثنى من ذلك حالات التقصير أو الإخلال بأحكام القانون أو مخالفة شروط نشرة الاكتتاب العام أو مذكرة المعلومات.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 3, ARRAY['699a06fd3b9262658b9240db7ed647c9']::text[], ARRAY['992e15787ca56ae110958d17e5f8e1b1']::text[], '78292f6cea0e6afcf656d8c03e52566a', replace($b$يجوز أن تصدر صكوك يطلق عليها متوافقة مع الشريعة الإسلامية أو إسلامية أو شرعية. كما يجوز أن يشار إلى أي من تلك العبارات في أي من عقودها أو نشرات طرحها أو وثائقها أو مواد الترويج لها أو الإعلانات الصادرة عنها ، وذلك وفقا للشروط الآتية:
( أ) أن تشكل لجنة رقابة شرعية للإصدار، وفقا للضوابط التي يصدر بها قرار من مجلس إدارة الهيئة بعد موافقة الأزهر الشريف ، ويحدد متطلبات تشكيل لجان الرقابة الشرعية واشتراطات عضويتها.
(ب) أن يكون المشروع محل التصكيك مجازا من لجنة الرقابة الشرعية بما يفيد توافقه مع أحكام الشريعة الإسلامية.
(جـ) أن تكون جميع التعاقدات الخاصة بإصدار الصكوك ونشرات الطرح المرتبطة به مجازة من لجنة الرقابة الشرعية بما يفيد توافقها مع أحكام الشريعة الإسلامية.
(د) أن يكون طلب قيد وتداول إصدار الصكوك بإحدى البورصات مجازا من لجنة الرقابة الشرعية.
وتلتزم لجنة الرقابة الشرعية منذ إصدار وحتى انتهاء استردادها بالتحقيق من استمرار توافقها مع أحكام الشرعية منذ إصدار الصكوك وحتى انتهاء استردادها بالتحقيق من استمرار توافقها مع أحكام الشريعة الإسلامية ، و إثبات ذلك فى تقارير دورية تعدها كل ثلاثة أشهر ، يتم نشرها على النحو الذى يحدده مجلس إدارة الهيئة.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 4, ARRAY['c984cbe17e05db1b66a5e0272b16dc06']::text[], ARRAY['82e28a05183dceef6ceb6fa65054b7b6']::text[], 'd33fb566aaf43d057655ac11155f15ef', replace($b$يتشرط في إصدار صكوك لتمويل نشاط أو مشروع معين أن يتوافر فيه ما يأتي:
(أ) أن يدر دخلا ، وفقا لدراسة تعد لهذا الغرض.
(ب) أن تديره إدارة متخصصة ، تتمتع بخبرة عالية في نوع النشاط.
(جـ) أن يكون النشاط أ، المشرع داخل جمهورية مصر العربية ، ما لم تكن الشركة أو الجهة مصرية.
(د) أن يكون له حسابات مالية مستقلة عن الأنشطة أو المشروعات الأخرى الخاصة بالجهة المصدرة والجهة المستفيدة وتستخرج منها القوائم المالية الدورية والسنوية.
(هـ) أن يتولى مراقبة حسابات المشروع مراقب حسابات أو أكثر ، تعبئه الجهة المصدرة من بين مراقبي الحسابات المسجلين لدى الهيئة.
(و) أن تصدر القوائم المالية للنشاط أو المشروع وتراجع وفقا لمعايير المحاسبة والمراجعة المشار إليها فى هذا القانون.
وتصدر الصكوك بالجنيه المصري أو بأي عملة من العملات الأجنبية القابلة للتحويل وذلك بمراعاة أحكام التشريعات المنظمة للتعامل بالنقد الأجنبي.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 5, ARRAY['f95d1e715dcd9169aae5f6f397ae6e12']::text[], ARRAY['29a801e2db06d1389a63dee981fb6a51']::text[], '09b07ec66ad326179889f5adf8497070', replace($b$تصدر الصكوك من خلال شركة تصكيك تتلقى حصيلة الاكتتاب في الصكوك، وتعمل وكيلا عن حملة الصكوك في متابعة استثمارها واستخدامها في الأغراض التي صدرت من أجلها، ومتابعة توزيع عوائد وقيمة استردادها، وتكون طرفا في جميع العقود مع الجهة المستفيدة من التمويل وغيرها من المشاركين في الإصدار نيابة عن مالكي الصكوك.
ويضع مجلس إدارة الهيئة الشروط والضوابط الخاصة بقيام الجهة المستفيدة بإصدار الصكوك بذاتها.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 6, ARRAY['5647914a8f3c838b8e489cf21794632b']::text[], ARRAY['bd5ced3a70484a6425ccb1d173621a23']::text[], 'b0cbc30dea67fd119773a42dc65f838f', replace($b$يجوز لشركة التصكيك أن تتعامل في أكثر من إصدار صك واحد حتى تمام سداده، بشرط أن يرخص بذلك من مجلس إدارة الهيئة وفقا للضوابط التي يضعها في هذا الشأن وبصفة خاصة إمساك حسابات مستقلة لكل إصدار، بما يترتب عليه اقتصار حقوق حملة كل إصدار من الصكوك على الأصول المرتبطة بالإصدار.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 7, ARRAY['4a2b725c0af14cad6e938537bbe4c990']::text[], ARRAY['3603fc72be45a32503557901cbc55dcd']::text[], '236c27131a6efcce10b8943b1b24c7f7', replace($b$يجوز للجهات التالية ، وبعد موافقة الهيئة ، الاستفادة من التمويل من خلال عقد إصدار صكوك:
(أ) شركات المساهمة الخاضعة لأحكام هذا القانون أو قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم 159 لسنة 1981 والتي يسمح نظامها الأساسي بذلك.
(ب) البنوك التي يسمح نظامها الأساسي بذلك ، بعد موافقة البنك المركزي المصري.
(جـ) الهيئات العامة وغيرها من الأشخاص الاعتبارية العامة ، بعد موافقة مجلس الوزراء بناء على عرض وزير المالية وبمراعاة حكم المادة (14مكررا -8).
(د) مؤسسات التمويل الدولية أو الإقليمية ، بعد موافقة مجلس إدارة البنك المركزي المصري.
ويحدد مجلس إدارة الهيئة الحدين الأدنى والأقصى لقيمة الصكوك لكل من الجهات المشار إليها ، كما يحدد أيضا الشروط و الإجراءات اللازمة للموافقة على إصدار صكوك للجهات الواردة في البند (د).
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 8, ARRAY['cff0aa2cd941e04e31c6cf588741f2e7']::text[], ARRAY['63447785106c4993ad0768003c4711c8']::text[], '5400e357cceaa3ce3be7c724548f8cfc', replace($b$يشترط حصول شركة أو بنك على موافقة الهيئة للاستفادة من التمويل من خلال عقد إصدار صكوك وما يرتبط به من تصكيك و إصدار صكوك ما يأتي:
(أ) التعاقد مع منظم للإصدار يتولى الإشراف على إعداد جميع المستندات و الإجراءات والتعاقدات ، ويتولى التعامل مع الهيئة في شأنها.
(ب) موافقة الجمعية العامة غير العادية على عقد إصدار الصكوك والتعهدات المرتبطة به ، و الالتزامات المترتبة عليه.
(جـ) تقديم نشرة الاكتتاب العام أو مذكرة المعلومات ، بحسب الأحوال ، وفقا لأحكام المادة (14 مكررا 9 ) من هذا القانون.
ويحدد مجلس إدارة الهيئة القواعد المنظمة للحد الأقصى لقيمة الصكوك المصدرة بمراعاة طبيعة المشروع ، أو النشاط المراد إصدار صكوك لتمويله.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 9, ARRAY['e000c1b05a827e2fc181aefe7f4a3f7b']::text[], ARRAY['12274ec6891dc813d6449bf615a0cbe4']::text[], 'ecae965da9ae5bb9cf5454c3c6ca913d', replace($b$للهيئات والأشخاص الاعتبارية العامة أن تصدر صكوك تكون هي الجهة المستفيدة منها ، على أن يتوافر فيها الآتي:
(أ) اعتماد وزارة المالية نشرة الاكتتاب ، أو مذكرة المعلومات لإصدار الصكوك ، وغيرها من المستندات والبيانات والإقرارات المرتبطة بالإصدار والمقدمة للهيئة.
(ب) أن يتولى مراقبة حسابات المشروع الجهاز المركزي للمحاسبات، إضافة إلى مراقب حسابات من بين المسجلين لدى الهيئة تختاره وزارة المالية.
(جـ) أن يكون رأسمال شركة التصكيك مملوكا بالكامل لبنوك قطاع عام أو شركات قطاع عام أو قطاع أعمال عام أو أى من الأشخاص الاعتبارية العامة.
(د) أن يكون لشركة التصكيك مراقبا حسابات أحدهما من الجهاز المركزي للمحاسبات.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 10, ARRAY['b14b86b513b20b7cb0c046244191fc62']::text[], ARRAY['bfd70b3c0d85a48c7089b7bac622a3e9']::text[], 'f3c6018a25aafcd558d7cf3fc7646ebb', replace($b$مع مراعاة أحكام المادة (4) من هذا القانون ، تنظيم اللائحة التنفيذية قواعد و إجراءات إصدار الصكوك وطرحها للاكتتاب العام أو الطرح الخاص ، وتغطيتها ، والبيانات التي يجب أن تتضمنها نشرة الاكتتاب أو مذكرة المعلومات لإصدار الصكوك ، والمستندات والبيانات والإقرارات التي يجب إرفاقها بها لاعتمادها من الهيئة ، على ان تتضمن شهادة بالتصنيف الائتماني للإصدار من إحدى جهات التصنيف المعتمدة لدى الهيئة ، و ألا تقل درجة التصنيف عن المستوى الدال على الوفاء بالالتزامات الواردة بنشرة الاكتتاب العام أو مذكرة المعلومات ، وذلك في الحالات التي تتطلب طبيعة الصك ذلك.
وتقوم الجهة المصدرة بطرح الصكوك بناء على نشرة اكتتاب عام ، أو مذكرة معلومات معتمدة من الهيئة ، ومعدة على النموذج المخصص لذلك ، ويتم نشرة الاكتتاب العام وفقا لأحكام المادة (4 ) من هذا القانون.
وتكون الشركة المصدرة للصكوك مسئولة عن صحة المستندات والبيانات والإقرارات المقدمة للهيئة ، وعن المعلومات الواردة في نشرة الاكتتاب العام أو مذكرة المعلومات ودقتها وشمولها ، وأي معلومات أو بيانات لها علاقة بعملية الإصدار يتم الإفصاح عنها.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 11, ARRAY['1d712940d9063e1ef3e19de5613793f1']::text[], ARRAY['6d45292734612709e865b5dea6a20faf']::text[], '2de716cef79dd0d4299cf1ac5c2c1a06', replace($b$تكون الجهة المصدرة للصكوك مسئولة عن الحقوق المقررة لحملة الصكوك وفقا للأحكام المنظمة لعمل شركات التصكيك الواردة في هذا القانون، وفى الحدود المنصوص عليها في نشرة الاكتتاب العام أو مذكرة المعلومات، وتلتزم الجهة المصدرة بتعيين وكيل سداد لها.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 12, ARRAY['f7aedd088aaadf58667b21143d569038']::text[], ARRAY['205b7adaa18b6a1f233b31a4d2dd3add']::text[], '3788f3210fd5fc86486b894c286d2677', replace($b$يجوز أن يكون للصكوك ضامن لتغطية الاكتتاب من الجهات المرخص لها بذلك من الهيئة فإذا كان الضامن بنكا وجب عليه الحصول على موافقة البنك المركزي المصري.
كما يجوز أن يكون للصكوك متعهد إعادة شراء أو متعهد استردادها من البنوك أو الشركات العاملة فى مجال الأوراق المالية ، ويلتزم بشرائها أو استردادها وفقا لما تحدده نشرة الاكتتاب أو مذكرة المعلومات.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 13, ARRAY['f7cd5e129aa13da2c3a9c66055d96fd7']::text[], ARRAY['94e73c208063cfb04011cc29e8564e9a']::text[], '94db7d47c639b7de412d4747cae779d5', replace($b$في حالة عدم اكتمال عملية إصدار الصكوك لعدم التغطية أو لأي سبب آخر، يعاد للمكتتبين جميع المبالغ التي دفعوها كاملة وذلك خلال يومي عمل من التاريخ المحدد لانتهاء مدة تغطية الاكتتاب أو الطرح، أو خلال المدة التي تحددها نشرة الاكتتاب أو مذكرة المعلومات في غيرها من حالات عدم اكتمال عملية الإصدار.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 14, ARRAY['c0fe0040948c1efe0eaeb02b0095ef27']::text[], ARRAY['052bbe9340c17ec7a4032d8e64872d34']::text[], '5d30fef8200d2ef806ca0d221d0eda21', replace($b$يجب أن يتم قيد الصكوك و إيداعها لدى شركة الإيداع والقيد المركزي وفقا لأحكام قانون الإيداع والقيد المركزي . وتحفظ الصكوك من خلال أحد أمناء الحفظ المرخص لهم من الهيئة ، ويتولى وكيل السداد توزيع العوائد و أداء القيمة الاستردادية عند حلول أجل الصك وفقا للأحكام الواردة بنشرة الاكتتاب أو مذكرة المعلومات.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 15, ARRAY['aab2dbaff9cade807058c668a97554c6']::text[], ARRAY['857a2abdd2b83b755c6fe9dab6159175']::text[], '0302a1b79c867c0b95663ede459fdef7', replace($b$يجب قيد الصكوك التي تطرح في اكتتاب عام للتداول في إحدى بورصات الأوراق المالية في مصر، كما يجوز إدراجها وتداولها في الأسواق المالية في الخارج بعد موافقة الهيئة، كما يجوز قيد الصكوك التي تطرح طرحا خاصا في إحدى بورصات الأوراق المالية بمصر، ويحدد مجلس إدارة الهيئة شروط وقواعد قيدها.
ويكون تداول الصكوك خارج بورصات الأوراق المالية وفقا للضوابط التي يصدر بها قرار من مجلس إدارة الهيئة.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 16, ARRAY['ff9a5a866800397f6b5a1a17e7dd07e4']::text[], ARRAY['42a6e30446f6a283e38c3e45fdcd9ab8']::text[], 'a52dcbf382609c87e4b377184478493b', replace($b$يجوز لمالكي الصكوك ذات الإصدار الواحد تكوين جماعة لحماية المصالح المشتركة لأعضائها، ويكون للجماعة ممثل قانوني من بين أعضائها، يتم اختياره وعزله وفقا للشروط والأوضاع التي تحددها اللائحة التنفيذية لهذا القانون. ويشترط ألا تكون له علاقة مباشرة أو غير مباشرة بالجهة المصدرة، و ألا تكون له مصلحة متعارضة مع مصلحة الجماعة.
ويتعين إخطار الهيئة والجهة المصدرة وشركة التصكيك بتشكيل هذه الجماعة ، واسم ممثلها ، وقراراتها. وتحدد اللائحة التنفيذية لهذا القانون إجراءات دعوة الجماعة للانعقاد ، وكيفية الانعقاد ، ومكانه ، والتصويت ، وعلاقة الجماعة بالجهة المصدرة.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 17, ARRAY['1013609c4ea27eae0db5a193233a7907']::text[], ARRAY['ee35067d4ad5a259af488d8e1ee903bd']::text[], 'b1f45fa931823474d1de999b2efac016', replace($b$تحدد اللائحة التنفيذية لهذا القانون متطلبات الإفصاح التي يجب أن تلتزم بها شركة التصكيك والجهة المستفيدة وغيرها من الجهات المشاركة في عملية إصدار الصكوك منذ الإصدار وحتى نهاية أجل الصك.
ويجب أن يتضمن الإفصاح تقارير مراقب الحسابات ، والقوائم المالية الدورية أو السنوية ، والتصنيف الائتماني الخاص بالصكوك ، و الأحداث الجوهرية ، والتعديلات على التعاقدات ، والتعهدات الواردة بنشرة الاكتتاب أو مذكرة المعلومات لإصدار الصكوك.
ويحدد مجلس إدارة الهيئة قواعد الإفصاح ومعاييره ومواعيده.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 18, ARRAY['60d0ba950ce770ad00b9badfe69e274f']::text[], ARRAY['4292e5873d7c78d58c55c7433588645f']::text[], 'ffafb377d1fec84159f3d69b9187f2e5', replace($b$يصدر مجلس إدارة الهيئة معايير المحاسبة والمراجعة التي تلتزم بها الشركات المصدرة للصكوك والشركات المستفيدة ومراقبو حساباتهم، وله أن يعتمد أي معايير محاسبة ومراجعة أخرى صادرة من إحدى الجهات الدولية ذات الاختصاص.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 19, ARRAY['a7d5dc29ae9fd0aa73bd5800cde3192e']::text[], ARRAY['b1c72601c1ebd55c05c023c947f1cae3']::text[], 'af7c09bcc47dd78b4bd41135ac1df65c', replace($b$تلتزم الجهة المستفيدة بأداء ناتج قيمة الصكوك في نهاية أجلها لمالكيها، وتتعهد بشراء موجوداتها القائمة في نهاية مدة الصكوك.
ويجوز التعهد بشراء هذه الموجودات قبل نهاية مدة الصكوك، وتحدد هذه القيمة وفقا للضوابط التي تتضمنها نشرة الاكتتاب.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (14, 20, ARRAY['a81f926d7849b7222c546e6e7dcc81cc']::text[], ARRAY['11f6be2173e9c5f8d03ce5290ee0afa6']::text[], 'd17bba257969aa87c45b6118a53f84a0', replace($b$تعفى من الضريبة على القيمة المضافة ، ومن جميع الضرائب والرسوم أيا كان نوعها ، جميع التصرفات التي تتم على الأصول فيما بين الجهة المستفيدة وبين شركة التصكيك شريطة عدم التصرف في هذه الأصول للغير أو تغيير هيكل ملكية شركة التصكيك ، ويشمل هذا الإعفاء ما يأتي:
(أ) التصرفات العقارية ، وتسجيل العقارات اللازمة لنقل ملكية الأصول العقارية التي تتم بين الجهة المصدرة وشركة التصكيك ، سواء عند إصدار الصكوك أو عند إعادتها للجهة المصدرة في نهاية مدة الإصدار.
(ب) تسجيل الموجودات والأصول والمنافع التي تتم بين الجهة المستفيدة وشركة التصكيك سواء عند إصدار الصكوك أو عند إعادتها للجهة المستفيدة في نهاية مدة الإصدار.
وتسرى على توزيعات العائد أو الأرباح المقررة لحملة الصكوك وعلى ناتج التعامل على الصكوك المعاملة الضريبية المقررة لسندات الشركات.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (15, 0, ARRAY['edbfc6850d77bc68f7a57be4bb505702']::text[], ARRAY['7eb1c8e0c346f0c3585ae4306326d554']::text[], '28ecd72cdadd67adaf2796f48565c655', replace($b$يتم قيد وتداول الأوراق المالية في سوق تسمى بورصة الأوراق المالية.
ويجوز قيد الورقة المالية أو الاداة المالية في أكثر من بورصة بموافقة الهيئة، ووفقا للشروط والضوابط التي يصدر بها قرار من مجلس إدارة الهيئة.
*الفقرة الثانية معدلة بموجب قانون رقم 17 لسنة 2018
نص المادة قبل التعديل : يتم قيد وتداول الأوراق المالية في سوق تسمى بورصة الأوراق المالية.
ولا يجوز قيد الورقة في أكثر من بورصة، واستثناء من ذلك تقيد الورقة المالية في بورصتي القاهرة والإسكندرية القائمتين في تاريخ العمل بهذا القانون، وذلك برسم قيد واحد يقسم بينهما.$b$, E'\n', E'\r\n')),
    (16, 0, ARRAY['b87222ba6049799db3dff5411d1e03a8']::text[], ARRAY['4a08115bd641252accbb6966f06eaa66']::text[], '54ebed69ff7913dd6243785abf17fad6', replace($b$تقيد الأوراق المالية في جداول البورصة بناء على طلب الجهة المصدرة لها، ويتم قيد الورقة وشطبها بقرار من إدارة البورصة وفقا للقواعد والشروط والأحكام التي يضعها مجلس إدارة الهيئة على أن يفرد جدول خاص تقيد به الأوراق المالية الأجنبية.
ويجوز أن تتضمن قواعد القيد شروطا خاصة للتصديق على بعض قرارات الجمعيات العامة للشركات لها أوراق مالية بالبورصة.
*معدلة بموجب القانون رقم 123 لسنة 2008 النص قبل التعديل : يكون قيد الأوراق المالية في جداول البورصة بناء على طلب الجهة المصدرة لها، ويتم قيد الورقة وشطبها بقرار من إدارة البورصة وفقا للقواعد التي يضعها مجلس إدارة الهيئة ويتم القيد في نوعين من الجداول:
(أ) جداول رسمية تقيد بها الأوراق المالية الآتية:
1- أسهم شركات الاكتتاب العام التي يتوافر فيها الشرطان الآتيان:
(أ) ألا يقل ما يطرح من الأسهم الاسمية للاكتتاب العام عن 30% من مجموع أسهم الشركة.
(ب) ألا يقل عدد المكتتبين في الأسهم المطروحة عن مائة وخمسين ولو كانوا من غير المصريين.
وإذا ترتب على تداول أسهم الشركة أن قل عدد المساهمين عن مائة لمدة تجاوز ثلاثة أشهر متصلة أو منفصلة خلال السنة المالية للشركة اعتبرت الأسهم مشطوبة من هذه الجداول بحكم القانون وتنقل إلى الجداول غير الرسمية.
2- السندات وصكوك التمويل والأوراق المالية الأخرى التي تطرحها شركات المساهمة وشركات التوصية بالأسهم في اكتتاب عام على أن تتوافر فيها الشروط الواردة بالبندين أ، ب من الفقرة السابقة.
3- الأوراق المالية التي تصدرها الدولة وتطرح في اكتتاب عام.
4- الأسهم والأوراق المالية الأخرى لشركات القطاع العام وشركات قطاع الأعمال العام.
(ب) جداول غير رسمية تقيد بها:
1- الأسهم وغيرها من الأوراق المالية التي لا تتوافر فيها شروط القيد في الجداول الرسمية.
2- الأوراق المالية الأجنبية.$b$, E'\n', E'\r\n')),
    (17, 0, ARRAY['571a7dfab0b30c970885f8feed744e70']::text[], ARRAY['8aae0fb45ee76db3f8086b7e9b631ec9']::text[], '92f47c216e0e5a6b326885c3c36367c7', replace($b$لا يجوز تداول الأوراق المالية المقيدة في أية بورصة خارجها وإلا وقع التداول باطلا.
ويصدر مجلس إدارة الهيئة قرارا بقواعد وإجراءات التعامل على الأوراق المالية غير المقيدة بجداول البورصات المصرية، وإجراءات نقل ملكيتها.
وعلى البورصة أن توافي الهيئة بالبيانات والتقارير الدورية التي تحددها اللائحة التنفيذية.
*الفقرة الثانية معدلة بموجب قانون رقم 17 لسنة 2018 نص المادة قبل التعديل: لا يجوز تداول الأوراق المالية المقيدة في أية بورصة خارجها وإلا وقع التداول باطلا.
ويتم الإعلان في البورصة عن عمليات تداول الأوراق المالية غير المقيدة، ذلك وفقا للقواعد التي يصدر بتنظيمها قرار من مجلس إدارة الهيئة.
وعلى البورصة أن توافي الهيئة بالبيانات والتقارير الدورية التي تحددها اللائحة التنفيذية.$b$, E'\n', E'\r\n')),
    (18, 0, ARRAY['444cc5a405e4a4669dca7d6c38effb43']::text[], ARRAY['12f61ae448af537d073213799f8669cf']::text[], 'cf4ff8959836df640ab451cd1ba90ee4', replace($b$في حالة قيد الأوراق المالية لدى إحدى الشركات المرخص لها بنشاط حفظ المركزي أو إدارة سجلات الأوراق المالية، تحل الوثائق التي تصدرها هذه الشركات محل صكوك الأوراق المالية في التعامل وحضور الجمعيات العامة للمساهمين وصرف الأرباح والرهن واستخدام حقوق الأولوية وغير ذلك وفقا للشروط والإجراءات التي تحددها اللائحة التنفيذية.
ويكون التعامل في الأوراق المالية المقيدة بالبورصة بواسطة إحدى الشركات المرخص لها بذلك وإلا وقع التعامل باطلا، وتضمن الشركة سلامة العملية التي تتم بواسطتها، وتبين اللائحة التنفيذية الأعمال التي يحظر على الشركة القيام بها.
*معدلة بموجب القانون رقم 158 لسنة 1998
النص قبل التعديل: يكون التعامل في الأوراق المالية المقيدة بالبورصة بواسطة مدى الشركات المرخص لها بذلك، وإلا وقع التعامل باطلا، وتضمن الشركة سلامة العملية التي تتم بواسطتها، وتبين اللائحة التنفيذية الأعمال التي يحظر على الشركة القيام بها.$b$, E'\n', E'\r\n')),
    (19, 0, ARRAY['f14fb03f00d9928dfb67ed9894b01b78']::text[], ARRAY['5f61f1228b8ac28e7ca97c5396e49197']::text[], '82b215c071b17fca041a0a672e1742f7', replace($b$تمسك كل بورصة سجلا تقيد به الشركات المرخص لها بالعمل في مجال الأوراق المالية التي تباشر نشاطها بها، ويتم القيد مقابل رسم مقداره عشرة آلاف جنيه واشتراك سنوي مقداره 1% من رأس مال الشركة بحد أقصى خمسة آلاف جنيه.$b$, E'\n', E'\r\n')),
    (20, 0, ARRAY['79e0a7bec8e6d9992cdf158cb1cea3b6']::text[], ARRAY['6e1fc8c5e88ea0bb30831644c4bafaff']::text[], '56f7f8dd020905a202d48956b15956cd', replace($b$تبين اللائحة التنفيذية الأحكام المنظمة لعقد عمليات التداول المقامة والتسوية في عمليات الأوراق المالية ونشر المعلومات عن التداول.$b$, E'\n', E'\r\n')),
    (20, 1, ARRAY['a100807b471b22713109272b27c11d49']::text[], ARRAY['6fdb72c3792eea782c2134fa9e51c402']::text[], 'bc96637a5ea2530fc8b7185cb6d4dbbb', replace($b$يحظر على الأشخاص الذين تتوافر لديهم معلومات عن المراكز المالية للشركات المقيدة بالبورصة أو نتائج أنشطتها وغيرها من المعلومات التي يكون من شأنها التأثير على أوضاع هذه الشركات، التعامل عليها لحسابهم الشخصي قبل الإعلان أو الإفصاح عنها للجمهور.
كما يحظر على هؤلاء الأشخاص إفشاء تلك المعلومات للغير بصورة مباشرة أو غير مباشرة.
وتحدد اللائحة التنفيذية لهذا القانون وقواعد القيد بالبورصة نوعية المعلومات التي يكون من شأنها التأثير على عمليات التداول.
*مضافة بموجب القانون رقم 123 لسنة 2008$b$, E'\n', E'\r\n')),
    (21, 0, ARRAY['1be320d57248725fd32a1bffe56f4be9']::text[], ARRAY['c1b04406cf17437c76c349e8fb63f279']::text[], '71a04f022bf0f5b1dc6f3fdeaae9c926', replace($b$يجوز بقرار من رئيس البورصة وقف عروض وطلبات التداول التي ترمي إلى التلاعب في الأسعار.
ويكون له إلغاء العمليات التي تعقد بالمخالفة لأحكام القوانين واللوائح والقرارات الصادرة تنفيذا لها أو التي تتم بسعر لا مبرر له.
كما يجوز له وقف التعامل على ورقة مالية إذا كان من شأن استمرار التعامل بها الإضرار بالسوق أو المتعاملين فيه.
ولرئيس الهيئة أن يتخذ في الوقت المناسب أيا من الإجراءات السابقة.$b$, E'\n', E'\r\n')),
    (21, 1, ARRAY['c57158a4c567b85f8d87e1bdffcca3de']::text[], ARRAY['027a45ed7560ef3dcd3b2b79c12a7f45']::text[], '612ca8f0f3e2834622c264ecfa69bdda', replace($b$لرئيس الهيئة إيقاف أحد المتعاملين عن شراء الأوراق المالية في بورصات الأوراق المالية المصرية، سواء كان العميل يتعامل باسمه ولحسابه أو لحساب أو لصالح مستفيد آخر، و إذا ارتكب مخالفة تتعلق بالتلاعب في أسعار الأوراق المالية، أو أي مخالفة أخرى لأحكام هذا القانون وذلك بناء على تحقيقات تجريها الهيئة، ويكون الإيقاف بقرار مسبب لمدة لا تجاوز ستة أشهر.
ولرئيس البورصة اتخاذ ذات الإجراءات الواردة في هذه المادة وفقا للضوابط التي يضعها مجلس إدارة الهيئة.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (22, 0, ARRAY['5cd98cc504b8fe8ca6f7557861f3a7b2']::text[], ARRAY['b3923df272a412407f7fdc2ec941519e']::text[], '8f655503e19f54497524cd80b86dfba2', replace($b$يجوز لرئيس الهيئة إذا طرأت ظروف خطيرة أن يقرر تعيين حد أعلى وحد أدنى لأسعار الأوراق المالية بأسعار القفل في اليوم السابق على القرار، وتفرض هذه الأسعار على المتعاقدين في جميع بورصات الأوراق المالية. ويبلغ القرار فور اتخاذه إلى الوزير، وللوزير أن يوقف تنفيذه، ويبين طريقة تعيين الأسعار ومراقبة الأعمال في البورصات.
وللوزير من تلقاء نفسه أن يصدر قرارا بما يتخذ من إجراءات الظروف المشار إليها.$b$, E'\n', E'\r\n')),
    (23, 0, ARRAY['d357cda55b16e88cab20e5d2334e22e8']::text[], ARRAY['491d45a9df160995b83c4cd69d6f6003']::text[], '2d97f42554e47bdd3672ff2d395d90cb', replace($b$ينشأ بقرار من رئيس مجلس الوزراء بناء على اقتراح مجلس إدارة الهيئة صندوق خاص لتأمين المتعاملين من المخاطر غير التجارية عن أنشطة الشركات المقيد لها أوراق أو أدوات مالية بالبورصات المصرية أو العاملة في مجال الأوراق المالية و الأدوات المالية.
وتكون له الشخصية المعنوية الخاصة.
ويحدد القرار الصادر به نظام إدارته ، وقواعد اشتراك الشركات المشار إليها في عضوية مجلس إدارته ، ونسبة مساهمة كل منها في موارده ، ومقابل التأخير في الوفاء بهذه المساهمة ، وأي مبالغ تستحق للصندوق عن المواعيد المحددة للوفاء بها ، وكذلك قواعد انفاق هذه الموارد واستثمارها ، والمخاطر التي يؤمنها الصندوق ، وأسس التعويض عنها ، وما يجب اتباعه بشأن الحسابات الخاصة بكل فئة من الفئات المشتركة في الصندوق ، وضوابط الصرف من هذه الحسابات على المخاطر التي يغطيها تبعا لكل فئة.
*معدلة بموجب قانون رقم 17 لسنة 2018 نص المادة قبل التعديل : ينشأ صندوق خاص تكون له الشخصية المعنوية لتأمين المتعاملين من المخاطر غير التجارية الناشئة عن أنشطة الشركات العاملة في مجال الأوراق المالية.
ويكون إنشاء هذا الصندوق بقرار من رئيس مجلس الوزراء بناء على عرض الوزير واقتراح مجلس إدارة الهيئة. ويتضمن قرار إنشاء الصندوق نظام إدارته وعلاقته بالشركات المشار إليها ونسبة مساهمة كل منها في موارده، ومقابل التأخير في الوفاء بهذه المساهمة وأية مبالغ مستحقة للصندوق عن المواعيد المحددة للوفاء بها، وكذلك قواعد إنفاق واستثمار هذا الموارد.
والمخاطر التي يؤمنها الصندوق وأسس التعويض عنها.
*الفقرة الثالثة معدلة بموجب القانون رقم 143 لسنة 2004 النص قبل التعديل : ينشأ صندوق خاص تكون له الشخصية المعنوية لتأمين المتعاملين من المخاطر غير التجارية الناشئة عن أنشطة الشركات العاملة في مجال الأوراق المالية.
ويكون إنشاء هذا الصندوق بقرار من رئيس مجلس الوزراء بناء على عرض الوزير واقتراح مجلس إدارة الهيئة. ويتضمن قرار إنشاء الصندوق نظام إدارته وعلاقته بالشركات المشار إليها ونسبة مساهمة كل منها في موارده، وقواعد إنفاق واستثمار هذه الموارد، والمخاطر التي يؤمنها الصندوق وأسس التعويض عنها.$b$, E'\n', E'\r\n')),
    (24, 0, ARRAY['a54f6a05ea9930073add17fd5533e2f4']::text[], ARRAY['c7b95f4e440d4cd47bb3c36dd93b8883']::text[], '139f55aaa1ba019d8d3bc210f84334aa', replace($b$يصدر الوزير المختص بناء على اقتراح مجلس إدارة الهيئة قرارا بنظام عمولات السمسرة ، والحدود القصوى لمقابل الخدمات عن العمليات التي تتم في البورصات ، ورسوم ومقابل قيد الأوراق المالية والأدوات المالية بما لا يجاوز سنويا اثنين في الألف من قيمة الأسهم والأدوات المالية المرتبطة بها ، والمطلوب قيدها بحد أقصى مقداره خمسمائة ألف جنيه ، وخمسون ألف جنيه كحد أقصى للسندات وصكوك الدين و أدوات الدين الأخرى. ولا تستحق الرسوم المنصوص عليها في هذه المادة على قيد الأوراق المالية أو الأدوات المالية التي تصدرها الدولة
*معدلة بموجب قانون رقم 17 لسنة 2018 نص المادة قبل التعديل : يصدر الوزير المختص بناء على اقتراح مجلس إدارة الهيئة قرارا بنظام عمولات السمسرة والحدود القصوى لمقابل الخدمات عن العمليات التي تتم في البورصات، كما يحدد رسوم قيد الأوراق المالية بها بواقع اثنين في الألف من قيمة رأس مال الشركة وبحد أقصى قدره خمسمائة ألف جنيه سنويا، ولا تستحق الرسوم المشار إليها على قيد الأوراق المالية التي تصدرها الدولة.
*معدلة بموجب القانون رقم 27 لسنة 2014 النص قبل التعديل : يصدر الوزير بناء على اقتراح مجلس إدارة الهيئة قرارا بنظام عمولات السمسرة والحدود القصوى لمقابل الخدمات عن العمليات التي تتم في البورصات.
كما يحدد رسوم قيد الأوراق المالية بالبورصة على ألا يتجاوز رسم القيد في الجداول المبينة بالبند (أ) من المادة 16 من هذا القانون خمسة آلاف جنيه سنويا عن كل إصدار وثلاثة آلاف جنيه سنويا عن كل إصدار للقيد في الجداول المبينة بالبند (ب) من المادة المذكورة.
ولا تستحق الرسوم المشار إليها على قيد الأوراق المالية التي تصدرها الدولة.$b$, E'\n', E'\r\n')),
    (25, 0, ARRAY['5ca31040452a614aa7436411978d7469']::text[], ARRAY['ed01a00297a7e7acb37ea912ed52911b']::text[], 'a6fc1511493cb4a70f392d22af7b7a92', replace($b$تستمر بورصتا القاهرة والإسكندرية في مباشرة نشاطهما كشخص اعتباري عام واحد تحت مسمى البورصة المصرية.
ويصدر بالأحكام المنظمة لإدارتها وشئونها المالية قرار من رئيس الجمهورية.
معدلة بموجب القانون رقم 123 لسنة 2008
النص قبل التعديل : تستمر بورصتا القاهرة والإسكندرية في مباشرة نشاطهما بالشخصية المعنوية المقررة لهما في تاريخ العمل بهذا القانون، ويصدر بالأحكام المنظمة لإدارتها وشئونها المالية قرار من رئيس الجمهورية. وإلى أن يصدر هذا القرار تطبق على البورصتين النظم المالية والإدارية التي كان معمولا بها في التاريخ المبين في الفقرة السابقة.$b$, E'\n', E'\r\n')),
    (26, 0, ARRAY['75eb3a54503ce51157a938482ebe3960']::text[], ARRAY['d6bce3a2c173b7cea0d893da558792a1']::text[], 'c5c895e7483c42c1fd65790f6781594a', replace($b$يجوز بموافقة مجلس إدارة الهيئة إنشاء بورصات ، تكون لها الشخصية المعنوية الخاصة ، تتخذ شكل شركة المساهمة ، ويقتصر التداول فيها على نوع أو أكثر من الأوراق المالية.
ولا يجوز للبورصة مزاولة نشاطها إلا بعد الحصول على ترخيص بذلك من الهيئة.
ويصدر مجلس إدارة الهيئة قرارا بالشروط التي يلزم توافرها في شركة المساهمة التي يجوز الترخيص لها بنشاط البورصة ، على أن يتضمن القرار المتطلبات الخاصة بالمساهمين ، ورأس المال ، وتشكيل مجلس الإدارة ، وقواعد الحوكمة ، وغيرها من العناصر الفنية والإدارية.
كما يصدر مجلس إدارة الهيئة قرارا بالضوابط المنظمة للتقدم بطلب الحصول على الموافقة على إنشاء بورصة خاصة ، على أن تتضمن تقديم دراسة فنية و إدارية ومالية للبورصة المطلوب إنشاؤها ، وكيفية التحقق من استيفاء الشروط المتطلبة في الشركة.
ويحدد مجلس إدارة الهيئة رسوم الترخيص بما لا يجاوز مائة ألف جنيه.
وتصدر الهيئة نموذج النظام الأساسي لشركة البورصة متضمنا القواعد التي تكفل حسن إدارتها وعلى الأخص ما يأتي:
الشروط الواجب توافرها في هيكل المساهمين بالشركة ، وأعضاء مجلس إدارتها ، والمديرين التنفيذيين ، وأعضاء لجنة العضوية ، وغيرها من اللجان.
قواعد تجنب حالات تعارض المصالح لدى أعضاء مجلس الإدارة والعاملين بالبورصة ، وعدم استخدام المعلومات المتوافرة لأى منهم لمصلحته الشخصية ، أو إفشائها للغير.
أسلوب تشكيل وتنظيم العمل بلجان البورصة.
اختصاص مجلس إدارة البورصة بإعداد القوائم المالية وفقا لمعايير المحاسبة المصرية.
ويكون للشركة مراقبان للحسابات من بين المقيدين بسجل مراقبي الحسابات بالهيئة ، يتم اختيارهما وتحديد أتعابهما بقرار من الجمعية العامة للشركة.
وتنظم اللائحة التنفيذية لهذا القانون إجراءات وقف نشاط البورصة اختياريا ، وما يترتب على ذلك ، و إجراءات تصفيتها في هذه الحالة.
وتسرى على شركة البورصة أحكام المادة (31) من هذا القانون.
*معدلة بموجب قانون رقم 17 لسنة 2018
نص المادة قبل التعديل : يجوز بترخيص من الوزير بناء على اقتراح مجلس إدارة الهيئة إنشاء بورصات تكون لها الشخصية المعنوية الخاصة يقتصر القيد والتداول فيها على نوع أو أكثر من الأوراق المالية، وتحدد اللائحة التنفيذية الأحكام المنظمة لهذه البورصات والتداول فيها.$b$, E'\n', E'\r\n')),
    (26, 1, ARRAY['27b9ae3a845bcc922d45f24cc2a8b6e2']::text[], ARRAY['f0b37e31df5c05c262dfc27789cce64f']::text[], 'e99d8f06866adb7f30bc80ce5597c765', replace($b$في تطبيق أحكام هذا الباب، يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها:
- بورصة العقود الآجلة : بورصة تنشأ وفقا لأحكام المادة (26 ) من هذا القانون ، يتم التداول فيها على العقود التي تشتق قيمتها من قيمة أصول مالية ، أو عينية ، أو مؤشرات الأسعار أو أوراق مالية أو سلع أو أدوات مالية أو غيرها من المؤشرات التي تحددها الهيئة ، سواء كانت في شكل عقود مستقبلية ، أو عقود خيارات ، أو عقود المبادلة ، وغيرها من العقود النمطية.
- العقود المستقبلية : عقود نمطية لشراء أو بيع سلع أو أوراق مالية أو غيرها من الأدوات المالية التي توافق عليها الهيئة ، يكون تنفيذها في موعد مستقبلي على أساس سعر تنفيذ يتفق عليه وقت إبرام العقد ، وتكون العقود المستقبلية على السلع منمطة وفقا للمواصفات والجودة والكمية ومكان التسليم ، بما يتفق مع القواعد التي تضعها إدارة البورصة.
عقود الخيارات : العقود التي تتوافر فيها شروط العقود المستقبلية ،متى كانت تعطى لمشترى العقد الحق في شراء أو بيع كمية محددة من السلع أو الأوراق المالية وغيرها من الأدوات المالية في تاريخ محدد أو خلال فترة زمنية محددة بسعر تنفيذ يتم الاتفاق عليه وقت إبرام العقد.
- عقود المبادلة : عقود المبادلة أصل أو مؤشر أو أداة مالية أو ورقة مالية أخرى ، وفقا لبنود العقد الذى يجب أن يحدد فيه وقت إبرامه سعر التنفيذ ( سعر المبادلة ) وتواريخ المبادلة ، وتاريخ انتهائه.
- التداول : شراء أو بيع العقود بما فيها العقود المستقبلية وعقود الخيارات أو عقود المبادلة أو غيرها من العقود المقيدة في جداول
البورصة ، وفقا لشروط التداول ببورصة العقود الآجلة التي يضعها مجلس إدارة البورصة ، ويعتمدها مجلس إدارة الهيئة.
شركة الوساطة في العقود : الشركة المرخص لها من الهيئة بمزاولة نشاط السمسرة والوساطة في شراء وبيع كافة أنواع العقود باسم ولحساب عملائها
- منفذ الأوامر : الشخص الطبيعة من العاملين لدى شركة الوساطة المرخص له من الهيئة بتنفيذ أوامر الشراء والبيع لكافة أنواع العقود
- الأعضاء المتعاملون على العقود : كل عضو بالبورصة يتعامل على العقود محل السلع يرخص له من الهيئة بذلك وفقا للشروط والقواعد التي يصدر بها قرار من مجلس إدارة الهيئة.
- مركز المقاصة والتسوية : الشركة أو الجهة المرخص لها بإتمام تسوية المراكز المالية الناشئة عن تداول وتنفيذ العقود بأنواعها المختلفة.
- المخازن المعتمدة للسلع : المخازن بأنواعها المختلفة التي تخزن بها السلع محل العقود وفقا للشروط والضوابط التي تحددها وحده الإشراف والرقابة على المخازن المعتمدة للسلع المنشأة بحكم المادة (26 مكررا 6).
- خبراء تصنيف السلع : الخبراء المرخص لهم من وحدة الإشراف والرقابة على المخازن المعتمدة للسلع لتصنيف وتحديد مواصفات الجودة ودرجات السلع محل العقود بأنواعها المختلفة.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 2, ARRAY['922f1efe09f2041577a60130525a277b']::text[], ARRAY['edc660cf41149f769eb6c7396753b939']::text[], '83bdcf38eaa077eb265778edb494e251', replace($b$مع مراعاة أحكام المادة (26 ) من هذا القانون ، يجب أن يكون لبورصة العقود الآجلة عقد تأسيس ونظام أساسي وفقا للنموذج الذى تضعه الهيئة ، وألا يقل رأسمالها المصدر و المدفوع نقدا عن عشرين مليون جنيه مصري. ويجوز للبورصة المصرية تأسيس شركة مساهمة لمزاولة نشاط بورصات العقود الآجلة ، ولها أن تزاول نشاط تداول العقود المشتقة من الأوراق المالية المقيدة بها دون الحاجة لتأسيس شركة.
ويصدر مجلس إدارة الهيئة قرارا بقواعد ومعايير وهيكل مساهمي بورصة العقود الآجلة.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 3, ARRAY['8b38d94acdbf9aae6fd86dce29f9a754']::text[], ARRAY['112e053603d8fb640c73c670efe4a3de']::text[], '11019cf6aefc63fbab0396321e1e318b', replace($b$يصدر مجلس إدارة الهيئة قرارا بأحكام وشروط وإجراءات الترخيص بمزاولة النشاط لبورصات العقود الآجلة، يتضمن الالتزام بأداء تأمين للهيئة، ومقدار قيمته، والإجراءات المنظمة للخصم منه، وأحوال وإجراءات استكماله، وإدارة الهيئة لحصيلته، ويجب أن يرفق بطلب الترخيص ما يأتي:
1. أنواع العقود التي يجرى التعامل عليها في البورصة من بين العقود المستقبلية أو عقود الخيارات أو عقود المبادلة أو غيرها من العقود النمطية.
2. قواعد وشروط العضوية بالبورصة.
3. كيفية الحصول على القيم والأسعار للأدوات أو المؤشرات أو السلع محل التعاقد.
4. كيفية الإعلان عن أسعار التنفيض والتسوية لكل نوع من أنواع العقود المنصوص عليها
5. لائحة التداول بالبورصة.
6. الحد الأدنى من متطلبات الضمانة مقابل التنفيذ.
7. المعايير المالية لتحقيق المساواة بين المتعاملين، ومنع التلاعب في السوق.
8. وصف لنظام التداول، وإجراءات تنفيذ العمليات حتى تمام التسوية.
9. نماذج الاتفاقات التي ستتعامل بها البورصة بما في ذلك الاتفاقات المتعلقة بالعضوية، والتداول، وإتمام عمليات المقاصة والتسوية الى تجربها البورصة بنفسها أو مع شركة مقاصة وتسوية بحسب الأحوال، ونماذج الاتفاقات الاستشارية مع الجهات ذات الخبرة.
10. الإجراءات التي تتخذها البورصة عند مخالفة قواعد العضوية أو قواعد التعامل في البورصة، ووسائل فض المنازعات التي تتيحها البورصة للمتعاملين فيها.
11. نسخة من ميثاق الشرف الذى يبين فيه التزامات وواجبات أعضاء مجلس الإدارة ، والعاملين بالبورصة ، و أعضاء البورصة.
ويجب على الهيئة دراسة طلب الترخيص ومرفقاته ، ولها في سبيل ذلك أن تطلب المستندات والبيانات التي تراها لازمة للتحقق من استيفاء متطلبات الترخيص ، وعلى الأخص ما يأتي:
(أ) مدى مناسبة المقر لمزاولة النشاط.
(ب) استيفاء التجهيزات الفنية اللازمة.
(جـ) توافر الشروط والكفاءة والخبرة للقائمين على إدارة البورصة.
(د) توافر نظم تأمين وحماية البيانات لنظم المعلومات والتداول والاتصالات.
ويحدد مجلس إدارة الهيئة رسوم الترخيص بما لا يجاوز مائة ألف جنيه.
ولا يجوز بعد صدور ترخيص بمزاولة النشاط للبورصة تعديل أي من اللوائح أو القواعد أو النماذج أو الإجراءات المشار إليها في هذه المادة إلا بعد الحصول على موافقة مسبقة من الهيئة.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 4, ARRAY['0fadcb5c2c02d8651e8c58e1b1327791']::text[], ARRAY['7f4348d5cbde97630cda61aa11b95f7e']::text[], '8319f036bf6ede8e9bc78c185834d985', replace($b$يتم التعامل على العقود ببورصة العقود الآجلة وفقا للصيغ والشروط التي يقرها مجلس إدارة الهيئة.
ويضع مجلس إدارة بورصة العقود الآجلة قواعد التداول اللازمة لضمان سلامة العمليات التي تجرى فيها وصحة الإجراءات المتبعة في شأنها ، على أن تتضمن أسس تحديد أسعار التنفيذ بالعقود ، والأسعار المرجعية للأدوات أو المنتجات أو السلع أو المؤشرات محل التعاقدات ، وتوقيتات التداول ، ونظام الضمانة وشروطه ، وكيفية التعامل مع العقود التي تخالف الاشتراطات المعمول بها أو لا يتم الوفاء بها ، ولا تكون هذه القواعد نافذة إلا بعد اعتمادها من الهيئة.
ويكون للبورصة في سبيل أداء عملها الحصول على المعلومات من الشركات الأعضاء لديها المرخص لها بالتعامل على العقود ، وعليها اتخاذ ما يلزم من إجراءات لحماية حرية المنافسة وضمان المساواة بين المتعاملين. وتلتزم البورصة بنشر المعلومات المرتبطة بالتعامل في سوق العقود ، و إتاحتها للمستثمرين وللجمهور ، من خلال موقعها الإلكتروني أو بأي وسيلة أخرى.
كما تلتزم بتزويد الهيئة بالبيانات والتقارير الدورية التي يصدر بتحديدها وبمواعيد تقديمها قرار من مجلس إدارة الهيئة.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 5, ARRAY['c8e701b4787b9994ae6575bc42430557']::text[], ARRAY['21fcf792227e73eba7db54edcd529ea1']::text[], '9577350849ef371315e16981980be410', replace($b$يصدر الوزير المختص بناء على اقتراح مجلس إدارة الهيئة قرارا بمقابل الخدمات عن العمليات التي تتم في بورصة العقود الآجلة .وتتكون موارد البورصة من:
1. الموارد التي تحصلها طبقا لأحكام هذا القانون.
2. مقابل الخدمات التي تقدمها للمتعاملين معها.
3. عائد استثمار أموالها.
4. المنح والهبات التي تقدم لها، والقروض المحلية والخارجية التي تعقد لصالحها ، وذلك وفقا للقواعد المقررة في هذا الشأن.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 6, ARRAY['6bd96afb7bc78b23703df9e216f840bf']::text[], ARRAY['75e071a4e289d7691960a44d77c90ead']::text[], 'bbd1a490471330bb2b3dc0f1271808ff', replace($b$تتم عمليات المقاصة والتسوية للعقود التي يجرى التعامل عليها في بورصات العقود الآجلة وفقا لأحكام قانون الإيداع والقيد المركزي للأوراق المالية الصادر بالقانون رقم 93 لسنة 2000 ولائحته التنفيذية من خلال شركة مقاصة وتسوية مرخص لها بذلك من الهيئة ، وفقا للضوابط التي يصدر بها قرار من مجلس إدارة الهيئة.
وعلى الجهة المرخص لها بمباشرة عمليات المقاصة والتسوية إصدار لائحة بقواعد إجراء المقاصة والتسوية ، ولا تكون هذه اللائحة نافذة إلا بعد اعتمادها من الهيئة.
وفى حالة التسوية المالية بالنسبة للعقود على السلع ، يتم تسليم السلع محل العقود وفقا للقواعد التي تضعها وحدة الإشراف والرقابة على المخازن المعتمدة للسلع.
ويسرى فيما عدا ما تقدم أحكام قانون الإيداع والقيد المركزي للأوراق المالية ولائحته التنفيذية.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 7, ARRAY['543fb65535cf20bcf3791b5b83c88584']::text[], ARRAY['de209a4472e0303cb1b5aeb86aa74359']::text[], '278c6acada56c05a942e9753c831aa32', replace($b$تنشأ بالوزارة المختصة بالتجارة الداخلية وحدة مستقلة ذات طابع خاص تسمى وحدة الإشراف والرقابة على المخازن المعتمدة للسلع تتولى التنظيم والإشراف والرقابة على المخازن المعتمدة للسلع وعلى خبراء تصنيفها، ولها في سبيل ذلك على الأخص ما يأتي:
وضع شروط ومتطلبات الترخيص بالمخازن المعتمدة للسلع ، وقواعد عملها .
الترخيص للمخازن المعتمدة للسلع بالعمل.
وضع شروط ومتطلبات الترخيص لخبراء تصنيف السلع ، وشروط استمرار الترخيص.
الترخيص لخبراء تصنيف السلع.
إصدار دليل الإجراءات المرتبطة بالتسوية بالتنسيق مع الجهة المختصة بالمقاصة والتسوية للعقود المتداولة. تحديد آلية توفير الأسعار المرجعية للتداولات الحاضرة لمختلف السلع ، وبالأخص السلع محل التعاقدات في بورصة العقود الآجلة.
التفتيش على المخازن.
التفتيش على اعمال خبراء تصنيف السلع.
فحص الأنزعة المتعلقة بالسلع ، وتصنيفها ، وتحديد معايير ودرجة جودتها ، وما يتصل بأعمال خبراء تصنيف السلع.
طلب تحريك الدعوى الجنائية من الهيئة في شأن مخالفات الجهات القائمة على إدارة المخازن المعتمدة للسلع أو مخالفات خبراء تصنيف السلع.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 8, ARRAY['cea68e3b5c2ee999c4852225ebaf8f2f']::text[], ARRAY['7554e38936c4db868f0fb9e74f499d26']::text[], 'b87d07dc572e0891ecc4ff2ca869f98c', replace($b$يكون لوحده الإشراف والرقابة على المخازن المعتمدة للسلع مجلس أمناء ، يصدر بتشكيله وتحديد المعاملة المالية لأعضائه قرار من الوزير المختص بالتجارة الداخلية.
ويتضمن تشكيل مجلس الأمناء ممثلين عن الجهات الآتية:
ممثلان عن وزارة التموين والتجارة الداخلية ، يحددهما الوزير المختص.
ممثل عن وزارة التجارة والصناعة ، يحدده الوزير المختص.
ممثل عن وزارة المالية ، يحدده الوزير المختص.
ممثل عن البنك المركزي المصري ، يحدده محافظ البنك المركزي.
ممثل عن الهيئة العامة للرقابة المالية ، يحدده رئيسها.
ممثل عن بورصة العقود الآجلة ، يحدده رئيس هذه البورصة.
ثلاثة خبراء في المجالات ذات الصلة يختار اثنين منهم الوزير المختص بالتجارة الداخلية ويختار الثالث رئيس الهيئة.
ويعين الوزير المختص بالتجارة الداخلية رئيس مجلس الأمناء من بين أعضاء المجلس ، كما يصدر قرارا بالنظام الأساسي واللوائح المالية والإدارية والهيكل التنظيمي للوحدة دون التقيد بالنظم والقواعد المعمول بها في الحكومة والقطاع العام وقطاع الأعمال العام ،
على أن تتضمن النظام الأساسي للوحدة ما يأتي:
نظام عمل الوحدة واختصاصاتها.
تنظيم الوحدة.
اختصاصات مجلس الأمناء.
تنظيم اجتماعات مجلس الأمناء.
تعيين المدير التنفيذي للوحدة ، وتحديد المعاملة المالية له.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 9, ARRAY['819dda2a1af2c51e7cccfc86ed3a73a7']::text[], ARRAY['c861da00015f3bdb3f73c3fa6a2d5c9c']::text[], '94a6f54fad4c94951f10f1855536a5a1', replace($b$تتكون موارد وحدة الإشراف والرقابة على المخازن المعتمدة للسلع من:
(أ) ما تخصصه الدولة لها من أموال وأصول.
(ب) مقابل الترخيص للمخازن المعتمدة للسلع وخبراء التصنيف.
(جـ) مقابل الخدمات التي تقدمها الوحدة، ومقابل الإشراف على المخازن المعتمدة للسلع و الأنشطة المرتبطة بها. (د) عائد استثمار أموال الوحدة.
ويصدر قرار من الوزير المختص بالتجارة الداخلية بتحديد مقابل الخدمات المشار إليه بناء على اقتراح من مجلس أمناء الوحدة.
وتكون للوحدة موازنة مستقلة ، وتبدأ السنة المالية لها مع بداية السنة المالية للدولة وتنتهى بنهايتها.
كما تكون للوحدة حسابات مصرفية خاصة بها في بنك أو أكثر من البنوك الخاضعة لإشراف ورقابة البنك المركزي المصري ، تودع فيها مواردها.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 10, ARRAY['700fe45e9b5148ab6eb605a34f4c9c79']::text[], ARRAY['3ca449dcc68e8e68fa6f25b0eb8df37b']::text[], '23cccdb2f02ebc1735b5c3e3a3eb3bee', replace($b$يتم تنفيذ العمليات داخل بورصة العقود الآجلة بواسطة منفذي الأوامر بشركات الوساطة لحساب العملاء والأعضاء المتعاملين لحسابهم الخاص.
وتمسك البورصة سجلا يقيد فيه الأعضاء والجهات المشار إليها في الفقرة السابقة التي تباشر نشاطها به ، ويحدد النظام الأساسي قواعد العضوية بالبورصة ، ومقابل القيد بالسجل و الاشتراك السنوي.
ويتم تأسيس شركات الوساطة في العقود الآجلة وفقا لأحكام المادة (27 ) من هذا القانون ، كما يجوز الترخيص بممارسة نشاط الوساطة في العقود لشركات الوساطة في الأوراق المالية ، وفقا للقواعد التي يصدر بها قرار من مجلس إدارة الهيئة.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 11, ARRAY['bc904094846263f124c834bfa224f258']::text[], ARRAY['7daa284e7376eb1aabd1da8e282436f5']::text[], '99efdec541b97736bcdac1f489c434ff', replace($b$لا يجوز أن يقل رأس المال المصدر والمدفوع نقدا لشركات الوساطة في العقود الآجلة عن عشرة ملايين جنيه مصري.
ويحدد مجلس إدارة الهيئة شروط الترخيص لشركات الوساطة على أن تتضمن ما يأتي:
1. شروط تجهيز المقر ، والتقارير الداخلية الواجب إصدارها ، والقواعد الداخلية للرقابة ، والكفاءة والخبرة للقائمين على إدارة الشركة ، ونظم المعلومات الواجب توافرها.
2. معايير الملاءة المالية لشركة الوساطة والتي يجب الالتزام بها طوال مدة مزاولة النشاط.
3. أداء تأمين تحدد قيمته ، والقواعد و الإجراءات المنظمة للخصم منه ، و أحوال وإجراءات استكماله ، و إدارة حصيلته.
4. رسوم الترخيص بما لا يجاوز عشرة آلاف جنيه.
5. ألا يكون قد سبق الحكم على أحد مؤسسي الشركة أو مديريها أو أحد أعضاء مجلس الإدارة خلال السنوات الخمس السابقة على تقديم طلب الترخيص بعقوبة جناية أو في جنحة ماسة بالشرف أو الأمانة، أو إحدى الجرائم المنصوص عليها في قوانين الشركات أو التجارة ، أو الحكم بإشهار إفلاسه ، ما لم يكن قد رد اعتباره.
كما يحدد مجلس إدارة الهيئة شروط ومتطلبات الترخيص الواجب توافرها في الأعضاء المتعاملين على العقود.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 12, ARRAY['00e47d519af8d94c4ad66bd15ca7f760']::text[], ARRAY['2be936089f76bf71822db637b2168868']::text[], '56a4d96d65c2d78c24a3bab916070d1b', replace($b$لا يجوز لأى شركة وساطة أن تفتح حسابا لأى عميل إلا بعد الإفصاح اللازم له عن المخاطر المرتبطة بالتعامل في العقود الآجلة ، ويحظر على الشركة أن تضمن للعميل عدم تحقق أي خسائر عن التعامل في بورصة العقود الآجلة ، أو وضع حد أقصى لها بحسب الأحوال ، أو عدم الخصم من الضمان النقدي المودع لديها لحسابه لتغطية مركزه ، وذلك كله وفقا للقواعد التي تضعها البورصة وتعتمدها الهيئة ، ويجب أن تشمل تلك القواعد بالإضافة إلى ما سبق ما يأتي:
(أ) ضوابط الإعلان عن الخدمات التي تقدمها شركة الوساطة و أنواع العقود.
(ب) متطلبات الإفصاح وفقا لفئات العملاء المختلفة.
(جـ) ضوابط التعامل مع شكاوى العملاء.
(د) ما يجب أن يتضمنه ملف العميل.
(هـ) وسائل إخطار عملاء الشركة وبيانات الإخطار وتوقيتاتها.
وتلتزم شركات الوساطة في بورصات العقود الآجلة بالاشتراك في صندوق تأمين المتعاملين المنصوص عليه في المادة (23) من هذا القانون ، وذلك لتغطية المخاطر غير التجارية الناشئة عن أنشطة الشركات العاملة في بورصات العقود الآجلة.
ويصدر رئيس مجلس الوزراء قرارا بقواعد تحديد اشتراك الشركات العاملة في بورصات العقود الآجلة في عضوية مجلس إدارة الصندوق المشار إليه ، ونسبة مساهمة كل شركة في موارده ، ومقابل التأخير في الوفاء بهذه المساهمة ، وأي مبالغ تستحق للصندوق نتيجة التأخير عن المواعيد المحددة للوفاء بها ، وكذلك قواعد إنفاق هذه الموارد واستثمارها . ويحدد هذا القرار ما يجب اتباعه في شأن الحسابات الخاصة بالمتعاملين في الأوراق المالية ، والحسابات الخاصة بالمتعاملين ببورصات العقود الآجلة ، وضوابط الصرف من هذه الحسابات على المخاطر التي يغطيها الصندوق.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 13, ARRAY['4f68fc26f62ca3ce207e9d0613dac224']::text[], ARRAY['51384320dad69b3d1d03790a5bb750e3']::text[], '487a37cfac8a7b7434b989cfeff05e84', replace($b$يجوز لشركة الوساطة التعامل في العقود لحسابها بشرط الإفصاح لبورصة العقود الآجلة والهيئة عن كافة تعاملات الشركة لحسابها الخاص أو لحساب العاملين بها ، وذلك وفقا للإجراءات التي تضعها البورصة وتعتمدها الهيئة. وتلتزم الشركة عند قيامها بالتعامل لحسابها بإعطاء الأولوية لأوامر العملاء ، ويحظر عليها الدخول في تعاقد بالبيع أو بالشراء مع أحد عملائها دون الحصول على موافقته المسبقة كتابة ، وبمراعاة الضوابط التي تضعها الهيئة.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 14, ARRAY['efcdec2afc1fbfe2eddaccca09d9eb6b']::text[], ARRAY['05a944820d1b2fb22220e24c7ac30c6a']::text[], 'a8c133a3626e5a04dbdfe118e1e429e8', replace($b$تسرى أحكام المادة (20 مكررا) من هذا القانون على الأشخاص الطبيعيين العاملين لدى بورصة العقود الآجلة ، أو شركات الوساطة في العقود الآجلة و الأعضاء المتعاملين على السلع ، وكل من لديه معلومات غير مفصح عنها للكافة عن العقود محل التعامل والسلع والأوراق المالية ذات الارتباط بهذه العقود.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 15, ARRAY['180498e53397007d7cc0ff8a7ff08656']::text[], ARRAY['feec8e6b21dbdc0c4d4ea2a6d804e747']::text[], '97a577c8e0a7caa4f6a53a834ac648f0', replace($b$تسرى على المتعاملين في بورصات العقود الآجلة أحكام المادتين (21) ، ( 21 مكررا) من هذا القانون.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 16, ARRAY['e9482e3e77c0ab591473be97cde5527a']::text[], ARRAY['a7fe61ea171be4dc8121e599841b8e7d']::text[], 'a770570e4eb84e26683bf80135c0adc5', replace($b$للهيئة في الظروف الطارئة التي تقدرها أن تطلب من بورصة العقود الآجلة أو الجهة القائمة بالمقاصة والتسوية فيها اتخاذ التدابير و الإجراءات التي تراها الهيئة لازمة أو ضرورية للحفاظ على استقرار حركة التداول في البورصة ، أو تصفية أي عقود مستقبلية أو عقود خيارات أو عقود مبادلة.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 17, ARRAY['faf30a662d4f7d85e853ae156dcc770a']::text[], ARRAY['2ebf4aa481080ce4806cce67b199a671']::text[], '55ea861c2ae43ee2100785b78243461a', replace($b$تسرى أحكام المادتين (30)، (31) من هذا القانون على شركات الوساطة في العقود الآجلة و الاعضاء المتعاملين على السلع.
ولرئيس الهيئة إلغاء الترخيص الممنوح لمنفذ الأوامر حال تكرار مخالفة قواعد العمل بناء على تقرير مخالفات تعده البورصة أو الإدارة المختصة بالهيئة.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (26, 18, ARRAY['72441ff9a51c871e39920281f4352149']::text[], ARRAY['080e796b1d9d75e8eeaa6d6bdfd3a313']::text[], 'f093260b69c3a1be5305890e86149a46', replace($b$تسرى على شركات الوساطة ببورصات العقود الآجلة الأحكام المتعلقة بالشركات العاملة في مجال الأوراق المالية الواردة بالباب الثالث من هذا القانون ، وذلك فيما لم يرد به نص خاص في هذا الباب وبما لا يتعارض مع أحكامه.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (27, 0, ARRAY['1368eeeb368ef98189078bd4d9c28c75']::text[], ARRAY['c70f0d63ca381a24370c7f6a0fd5e7d5']::text[], '8f3a74f5f27f68fa8be5b75df9247ade', replace($b$تسري أحكام هذا الباب على جميع الشركات العاملة في مجال الأوراق المالية، ويقصد بها الشركات التي تباشر نشاطا أو أكثر من الأنشطة التالية:
(أ) ترويج وتغطية الاكتتاب في الأوراق المالية.
(ب) الاشتراك في تأسيس الشركات التي تصدر أوراقا مالية أو في زيادة رؤوس أموالها.
(ج) رأس المال المخاطر.
(د) المقاصة والتسوية في معاملات الأوراق المالية.
(هـ) تكوين وإدارة محافظ الأوراق المالية وصناديق الاستثمار.
(و) السمسرة في الأوراق المالية.
ويجوز للوزير بعد موافقة مجلس إدارة الهيئة إضافة أنشطة أخرى تتصل بمجال الأوراق المالية.
(ز) التعامل والوساطة والسمسرة في السندات وتبين اللائحة التنفيذية شروط وأوضاع مزاولة هذا النشاط.
(ح) نشاط توريق الحقوق المالية.
(ت) الاستشارات المالية عن الأوراق المالية.
(ي) نشاط صانع السوق ويقصد بنشاط صانع السوق توفير السيولة الدائمة للأوراق المالية المقيدة بإحدى بورصات الأوراق المالية التي يلتزم بصناعة سوقها وذلك بضمان التعامل عليها خلال جلسة التداول.
(ك) نشاط خدمات الإدارة في مجال صناديق الاستثمار.
وتقدم طلبات تأسيس هذه الشركات إلى الهيئة، وتبين اللائحة التنفيذية إجراءات وأوضاع تأسيسها والأحكام المنظمة لعملها والأعمال التي تدخل في تلك الأنشطة.
*إضافة بقرار وزير الاقتصاد والتجارة الخارجية رقم 697 لسنة 2001
*إضافة بقرار وزير الاقتصاد والتجارة الخارجية رقم 43 لسنة 2000
*إضافة بقرار وزير الاستثمار رقم 101 لسنة 2007
*إضافة بقرار وزير الاستثمار رقم 295 لسنة 2007
*إضافة بقرار وزير الاستثمار رقم 293 لسنة 2007$b$, E'\n', E'\r\n')),
    (28, 0, ARRAY['f40f8cb542e88fff3a063907d9b76a8f']::text[], ARRAY['e2f824d96b8cb53e9e0b29a32ddfa432']::text[], '6acdcafa34e450179f2dff5864e94ad4', replace($b$لا يجوز مزاولة الأنشطة المنصوص عليها في المادة السابقة إلا بعد الحصول على ترخيص بذلك من الهيئة والقيد بالسجل المعد لديها لهذا الغرض.
وتصدر الهيئة قرارها بالبت في طلب الترخيص خلال ستين يوما على الأكثر من تاريخ تقديم الأوراق مستوفاة إليها، وفي حالة رفض الطلب يجب أن يكون القرار مسببا، ويكون التظلم منه أمام لجنة التظلمات المنصوص عليها في الباب الخامس من هذا القانون.
وتحدد اللائحة التنفيذية قواعد وإجراءات ورسوم منح الترخيص بما لا يجاوز عشرة آلاف جنيه.
ويضع مجلس إدارة الهيئة نموذج الترخيص وبيانات السجل.
وعلى رئيس الهيئة وقف أي نشاط خاضع لأحكام هذا القانون إذا تمت مزاولته دون ترخيص، ويجوز أن يتضمن قرار الوقف غلق المكان الذي تتم مزاولة النشاط فيه بالطريق الإداري.$b$, E'\n', E'\r\n')),
    (28, 1, ARRAY['bc0453fa3770f2969cb4ee5b8ac006cb']::text[], ARRAY['78c303879eb865b3940e0e1c5e1ec5e2']::text[], '587213a1b6a63d256c2b796690660fc9', replace($b$ينشأ بالهيئة سجل تقيد به الشركات المرخص لها بالقيام بأعمال التقييم المالي وإعداد دراسات تحديد القيمة العادلة في جميع الحالات التي يتطلب فيها ذلك هذا القانون أو لائحته التنفيذية أو القرارات الصادرة تنفيذا لهما.
وتلتزم هذه الشركات عند قيامها بأعمال التقييم المالي وإعداد دراسات تحديد القيمة العادلة بمعايير التقييم المالي التي يصدر بها قرار من مجلس إدارة الهيئة.
ويضع مجلس إدارة الهيئة ضوابط القيد والشطب بالسجل.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (29, 0, ARRAY['48888b50b9fdc46fc035b14e22c6970d']::text[], ARRAY['5fe8ab6a5aeb467c8b28ddeb031bf8fe']::text[], '979d5c2e0787e4f54247016d35ca0e79', replace($b$يشترط لمنح الترخيص المنصوص عليه في المادة السابقة ما يأتي:
(أ) أن يكون طالب الترخيص شركة مساهمة أو شركة توصية بالأسهم.
(ب) أن يقتصر غرض الشركة على مزاولة نشاط أو أكثر من الأنشطة المبينة في المادة 27 من هذا القانون. (جـ) ألا يقل رأس مال الشركة المصدر وما يكون مدفوعا منه عنه التأسيس عن الحد الأدنى الذي تحدده اللائحة التنفيذية بحسب نوع الشركة وغرضها.
(د) أن يتوافر في القائمين على إدارة الشركة الخبرة والكفاءة اللازمة لعملها على النحو الذي يصدر به قرار من مجلس إدارة الهيئة.
(هـ) أداء تأمين يحدد قيمته والقواعد والإجراءات المنظمة للخصم منه واستكماله وإدارة حصيلته ورده قرار من مجلس إدارة الهيئة.
(و) ألا يكون قد سبق الحكم على أحد مؤسسي الشركة أو مديريها أو أحد أعضاء مجلس الإدارة خلال الخمس سنوات السابقة على تقديم طلب الترخيص بعقوبة جناية أو بعقوبة جنحة في جريمة ماسة بالشرف أو الأمانة أو إحدى الجرائم المنصوص عليها في قوانين الشركات أو التجارة أو الحكم بإشهار الإفلاس، ما لم يكن قد رد إليه اعتباره.$b$, E'\n', E'\r\n')),
    (30, 0, ARRAY['1ed870b31ebc8c7e1761aabba881706c']::text[], ARRAY['197d3709a82aefa5f640447b9c5e7371']::text[], 'cb0b20b3bc171a2a33b218b673574312', replace($b$يجوز وقف نشاط الشركة إذا خالفت أحكام هذا القانون أو لائحته التنفيذية أو قرارات مجلس إدارة الهيئة الصادرة تنفيذا له أو إذا فقدت أي شرط من شروط الترخيص ولم تقم بعد إنذارها بإزالة المخالفة أو استكمال شروط الترخيص خلال المدة وبالشروط التي يحددها رئيس الهيئة.
ويصدر بالوقف قرار مسبب من رئيس الهيئة لمدة لا تجاوز ثلاثين يوما، ويحدد القرار ما يتخذ من إجراءات خلال مدة الوقف، ويسلم القرار للشركة أو تخطر به بكتاب موصى عليه مصحوب بعلم الوصول، ويعلن عن ذلك في صحيفتين صباحيتين يوميتين واسعتي الانتشار على نفقة الشركة.
فإذا انتهت هذه المدة دون قيام الشركة بإزالة الأسباب التي تم الوقف من أجلها، تعين عرض الأمر على مجلس إدارة الهيئة لإصدار قرار بإلغاء الترخيص.$b$, E'\n', E'\r\n')),
    (31, 0, ARRAY['13ace23aa60d42a9901c1ced4af3442e']::text[], ARRAY['80a5746ee3698f5f6e20d5be23822e6c']::text[], '9cc69922956b2ba0aa3e9c6447a34501', replace($b$لمجلس إدارة الهيئة إذا قام خطر يهدد استقرار سوق رأس المال أو مصالح المساهمين في الشركة أو المتعاملين معها أن يتخذ ما يراه من التدابير الآتية:
(أ) توجيه تنبيه إلى الشركة.
(ب) منع الشركة من مزاولة كل أو بعض الأنشطة المرخص لها بمزاولتها.
(ج) مطالبة رئيس مجلس إدارة الشركة بدعوة المجلس إلى الانعقاد للنظر في أمر المخالفات المنسوبة إلى الشركة واتخاذ اللازم نحو إزالتها ويحضر اجتماع مجلس الإدارة في هذه الحالة ممثل أو أكثر عن الهيئة.
(د) تعيين عضو مراقب مجلس إدارة الشركة وذلك للمدة التي يحددها مجلس إدارة الهيئة ويكون لهذا العضو المشاركة في مناقشات المجلس وتسجيل رأيه فيما يتخذ من القرارات.
(هـ) حل مجلس الإدارة وتعيين مفوض لإدارة الشركة مؤقتا لحين تعيين مجلس إدارة جديد بالأداة القانونية المقررة.
(و) إلزام الشركة المخالفة بزيادة قيمة التأمين المودع منها.
استدراك - تصحيح خطأ لسنة 1992 - بشأن استدراك نشر بالعدد 29 من الجريدة الرسمية الصادر بتاريخ 16 يوليه سنة 1992 استدراك لقانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992.$b$, E'\n', E'\r\n')),
    (32, 0, ARRAY['8fc974e15325194c4d0dc30cf3eddaa8']::text[], ARRAY['9002028c456a22fda86bf7d9e3ff09c4']::text[], 'dad4e2e26cb6404f7c335dc1768012e2', replace($b$يكون التظلم من القرارات الصادرة وفقا لأحكام المواد السابقة أمام لجنة التظلمات المنصوص عليها في الباب الخامس من هذا القانون خلال خمسة عشر يوما من تاريخ إبلاغ صاحب الشأن بالقرار أو علمه به.
ولا تقبل الدعوى بطلب إلغاء تلك القرارات قبل التظلم منها طبقا للفقرة السابقة.$b$, E'\n', E'\r\n')),
    (33, 0, ARRAY['67e2a86b60f0acdf657d9251cb7a76ce']::text[], ARRAY['fce7340737f398c2e8d89da6e136b17e']::text[], '5f0d965b5ea4c89a5543076d4bbac95c', replace($b$لا يجوز لأية شركة وقف نشاطها أو تصفية عملياتها إلا بموافقة مجلس إدارة الهيئة، وذلك بعد التثبت من أن الشركة أبرأت ذمتها نهائيا من التزاماتها وفقا للشروط والإجراءات التي يحددها مجلس إدارة الهيئة.$b$, E'\n', E'\r\n')),
    (34, 0, ARRAY['4f4973a0f2817d935a3d4e1f183576c8']::text[], ARRAY['40de896e4d740f169ae727a5b7d764a7']::text[], '8bca6ff74cb578222d59b096b42f9864', replace($b$على كل من يباشر في تاريخ العمل بهذا القانون أحد الأنشطة المنصوص عليها في المادة (27) منه أن يعدل أوضاعه وفقا لأحكام هذا القانون والقرارات المنفذة له، وذلك خلال ستة أشهر من تاريخ العمل باللائحة التنفيذية لهذا القانون، ويجوز بقرار من مجلس إدارة الهيئة مد هذه المدة ستة أشهر أخرى.$b$, E'\n', E'\r\n')),
    (35, 0, ARRAY['8c392a57d570b86866bb56cd393fae5e']::text[], ARRAY['60f7d9c6755c6c91002e57a7185f8dcb']::text[], '0788f3cd62c57aa29b0ff9a539c0861e', replace($b$يجوز إنشاء صناديق استثمار تهدف إلى استثمار المدخرات في الأوراق المالية في الحدود ووفقا للأوضاع التي تبينها اللائحة التنفيذية لهذا القانون.
ولمجلس إدارة الهيئة أن يرخص للصندوق بالتعامل في القيم المالية المنقولة الأخرى أو في غيرها من مجالات الاستثمار ، طبقا للقواعد والشروط التي تحددها اللائحة التنفيذية لهذا القانون.
ويجب أن يتخذ صندوق الاستثمار شكل شركة المساهمة برأسمال نقدى ، ويحدد مجلس إدارة الهيئة ضوابط هيكل تشكيل مجلس الإدارة بمراعاة طبيعة نشاط صناديق الاستثمار.
*معدلة بموجب قانون رقم 17 لسنة 2018 نص المادة قبل التعديل : يجوز إنشاء صناديق استثمار تهدف إلى استثمار المدخرات في الأوراق المالية في الحدود وفقا للأوضاع التي تبينها اللائحة التنفيذية.
ولمجلس إدارة الهيئة أن يرخص للصندوق بالتعامل في القيم المالية المنقولة الأخرى أو في غيرها من مجالات الاستثمار طبقا للقواعد والشروط التي تحددها اللائحة التنفيذية.
ويجب أن يتخذ صندوق الاستثمار شكل شركة المساهمة برأسمال نقدي، وأن تكون أغلبية أعضاء مجلس إدارته من غير المساهمين فيه، أو المتعاملين معه، أو من تربطهم به علاقة أو مصلحة.
وعلى الصندوق أن يعهد بإدارة نشاطه إلى إحدى الجهات المتخصصة وفقا لما تحدده اللائحة التنفيذية.$b$, E'\n', E'\r\n')),
    (36, 0, ARRAY['8ad4e8b7116811f6fc48ef86625b6878']::text[], ARRAY['8fd2e3c4fbbe1d7251f2ccc4568a83ff']::text[], 'd6802df7de60916ad41ab086beee1376', replace($b$يحدد النظام الأساسي لصندوق الاستثمار النسبة بين رأس ماله المدفوع وبين أموال المستثمرين بما لا يجاوز ما تحدده اللائحة التنفيذية.
ويصدر الصندوق مقابل هذه الأموال أوراقا مالية في صورة وثائق استثمار يشارك حاملوها في نتائج استثمارات الصندوق.
ويتم الاكتتاب في هذه الوثائق عن طريق أحد البنوك ، أو الشركات العاملة في مجال الأوراق المالية التي ترخص لها الهيئة بذلك ، ووفقا للضوابط التي يضعها مجلس إدارة الهيئة.
*الفقرة الثالثة معدلة بموجب قانون رقم 17 لسنة 2018 نص المادة قبل التعديل : يحدد النظام الأساسي لصندوق الاستثمار النسبة بين رأس ماله المدفوع وبين أموال المستثمرين بما لا يجاوز ما تحدده اللائحة التنفيذية. ويصدر الصندوق مقابل هذه الأموال أوراقا مالية في صورة وثائق استثمار يشارك حاملوها في نتائج استثمارات الصندوق.
ويتم الاكتتاب في هذه الوثائق عن طريق أحد البنوك المرخص لها بذلك من الوزير.
ويضع مجلس إدارة الهيئة إجراءات إصدار تلك الوثائق واسترداد قيمتها والبيانات التي تتضمنها وقواعد قيدها وتداولها في البورصة.$b$, E'\n', E'\r\n')),
    (37, 0, ARRAY['ca94eeb68c41f2df6179e727df23c934']::text[], ARRAY['a6ff06b53ac9a3485dbf8073ddc6e6a3']::text[], '1c78c106ef85a00e69c04af25b1654fc', replace($b$يجب أن تتضمن نشرات الاكتتاب في وثائق الاستثمار التي تطرحها صناديق الاستثمار للاكتتاب العام، البيانات الإضافية الآتية:
1- السياسات الاستثمارية.
2- طريقة توزيع الأرباح السنوية وأسلوب معاملة الأرباح الرأسمالية.
3- اسم الجهة التي تتولى إدارة نشاط الصندوق وملخص واف عن أعمالها السابقة.
4- طريقة التقييم الدوري لأصول الصندوق وإجراءات استرداد قيمة وثائق الاستثمار.$b$, E'\n', E'\r\n')),
    (38, 0, ARRAY['815fe92842ba3ec2dba28783eeaa14cc']::text[], ARRAY['db4dc7477a5c3927ec116da79c0e677b']::text[], '84d74ba900c754a93c26bab8f6f25990', replace($b$يحتفظ بالأوراق المالية التي يستثمر الصندوق أموالا فيها لدى أحد البنوك المرخص لها من الهيئة بنشاط أمناء الحفظ والخاضعة لإشراف البنك المركزي المصري ، على ألا يكون البنك و أطرافه المرتبطة مسيطرا على شركة إدارة الصندوق أو مساهما فيها بنسبة تزيد على الحد الذى يحدده مجلس إدارة الهيئة ، وبمراعاة قواعد تجنب تعارض المصالح التي يحددها مجلس إدارة الهيئة.
ويقدم الصندوق إلى الهيئة بيانا عن الأوراق المشار إليها معتمدا من أمين الحفظ على النموذج وفى المواعيد التي تحددها الهيئة.
*معدلة بموجب قانون رقم 17 لسنة 2018 نص المادة قبل التعديل : يحتفظ بالأوراق المالية التي يستثمر الصندوق أموالا فيها لدى أحد البنوك الخاضعة لإشراف البنك المركزي المصري، على ألا يكون هذا البنك مالكا أو مساهما في الشركة المالكة للصندوق، أو الشركة التي تتولى إدارة نشاطه، وعلى أن يقدم الصندوق إلى الهيئة بيانا عن تلك الأوراق معتمدا من البنك على النموذج الذي يضعه مجلس إدارة الهيئة.$b$, E'\n', E'\r\n')),
    (39, 0, ARRAY['439a51306daebece6140a04d68c82ec8']::text[], ARRAY['9f846ce7977c7417d9560e2d6e2e4d4b']::text[], 'bdc0baa7372195d59c33230c8ed97a50', replace($b$يجب إخطار رئيس الهيئة بالقرارات التي تصدر بتعيين أعضاء مجالس الإدارة والمديرين المسئولين عن الإدارة العامة لأعمال الصندوق وبجميع البيانات المتعلقة بها خلال ثلاثين يوما من تاريخ صدور القرارات المشار إليها، ويتم الإخطار على النموذج الذي تضعه الهيئة.
ولمجلس إدارة الهيئة للحفاظ على سلامة أموال المستثمرين بالصندوق أن يصدر قرارا مسببا باستبعاد أي من أعضاء مجلس الإدارة أو المديرين المشار إليهم.
ولصاحب الشأن التظلم من قرار استبعاده أمام لجنة التظلمات المنصوص عليها في الباب الخامس من هذا القانون خلال ستين يوما من تاريخ إبلاغه بالقرار.$b$, E'\n', E'\r\n')),
    (40, 0, ARRAY['136420624c2b17747e340ca1d6ff07ea']::text[], ARRAY['21aa21eabb0f9936b61f0e4ca524b647']::text[], 'd380ab7995195caec96448c26e355496', replace($b$يتولى مراجعة حسابات الصندوق مراقبان للحسابات يختاران من بين المقيدين في سجل يعد لهذا الغرض بالتشاور بين الهيئة والجهاز المركزي للمحاسبات، ولا يجوز للمراقب الواحد أن يراجع حسابات أكثر من صندوقين في وقت واحد.
وتسري أحكام المادة (6) من هذا القانون على الصندوق ولو لم يطرح أوراقا مالية للاكتتاب العام.$b$, E'\n', E'\r\n')),
    (41, 0, ARRAY['0fc6288a4e47559c527ee6b4e0d68005']::text[], ARRAY['91b83612ba719b1fc8f8aed129f8f0b7']::text[], 'd9f42c7411b117fbdb2d145a0a793cc7', replace($b$يجوز للبنوك بعد موافقة البنك المركزي المصري ، وللشركات التي تباشر أنشطة مالية غير مصرفية التي يصدر بتحديدها قرار من مجلس إدارة الهيئة ، أن تباشر بنفسها أو مع غيرها ، نشاط صناديق الاستثمار بترخيص من الهيئة.
ويصدر مجلس إدارة الهيئة قواعد وضوابط و إجراءات الترخيص ومباشرة النشاط وإشراف ورقابة الهيئة.
*معدلة بموجب قانون رقم 17 لسنة 2018 نص المادة قبل التعديل : يجوز للبنوك وشركات التأمين بترخيص من الهيئة بعد موافقة البنك المركزي المصري، أو الهيئة المصرية العامة للرقابة على التأمين، حسب الأحوال، أن تباشر بنفسها نشاط صناديق الاستثمار، وتنظم اللائحة التنفيذية إجراءات الترخيص وأحكام وضوابط مباشرة ذلك النشاط وإشراف الهيئة عليه.$b$, E'\n', E'\r\n')),
    (41, 1, ARRAY['440be8017c625027d62ff7adcc39b93a']::text[], ARRAY['b7642c333cf1cbbd9fef6c6648b133ec']::text[], 'de4b0f1afbaa634f865acd794473565d', replace($b$شركة التوريق هي التي تزاول نشاط إصدار سندات قابلة للتداول في حدود ما يحال إليها من حقوق مالية ومستحقات آجلة الدفع بالضمانات المقررة لها، وتعد شركة التوريق - في تطبيق أحكام هذا القانون - من الشركات العاملة في مجال الأوراق المالية.
ويطلق على الحقوق والمستحقات والضمانات المحالة اسم محفظة التوريق.
ويقتصر غرض هذه الشركات على مزاولة النشاط المشار إليه دون غيره، ولا يجوز بغير ترخيص من مجلس إدارة الشركة أن يحال إليها أكثر من محفظة توريق واحدة، أو أن بأكثر من إصدار واحد للسندات، وذلك طبقا للقواعد والإجراءات التي يصدر بها قرار من مجلس الإدارة.
ويجوز لشركة التوريق إصدار سندات قابلة للتداول توجه حصيلتها لتمويل الأشخاص الاعتبارية العامة أو الخاصة بعد موافقة السلطة المختصة بها مقابل ما ينشأ لصالح هذه الجهات من تدفقات نقدية مستقبلية ، ويقصد بالتدفقات النقدية المستقبلية التدفقات المتوقع دخولها في المستقبل في ذمة المحيل طبقا للمجرى العادي للأمور ، ويشترط في تلك التدفقات الآتي:
1- أن تكون ناشئة لصالح الأشخاص الاعتبارية العامة أو الخاصة.
2- ألا تكون مقيدة أو مشروطة.
3- أن تكون خالية من أي حقوق حالية أو مستقبلية للغير.
ويُصدر مجلس إدارة الهيئة القرارات التنفيذية اللازمة لإصدار السندات المشار إليها بالفقرة الرابعة من هذه المـادة.
*الفقرة الرابعة والخامسة مضافة بموجب قانون رقم 13 لسنة 2022.
*مضافة بموجب القانون رقم 143 لسنة 2004$b$, E'\n', E'\r\n')),
    (41, 2, ARRAY['5668d9deff77350fc438e8caef0a1ef8']::text[], ARRAY['5382b5448fb91659d48756a97f56cc6f']::text[], 'd68540d6234ff6ce56583d7fff30ba95', replace($b$تتم حوالة محفظة التوريق بموجب اتفاق بين المحيل وشركة التوريق المحال إليها وفقا للنموذج الذي تعهده الهيئة ويجب أن تكون الحوالة نافذة وناجزة وغير معلقة على شرط وناقلة لجميع الحقوق والمستحقات والضمانات المحالة، وأن يكون المحيل ضامنا لوجودها وقت الحوالة، ولا يكون مسئولا عن الوفاء بأي منها بعد إتمام الحوالة إلى شركة التوريق ويجب إخطار الهيئة بذلك ونشر ملخص واف لاتفاق الحوالة في جريدتين يوميتين صباحيتين واسعتي الانتشار إحداهما على الأقل باللغة العربية.
ويتولى المحيل تحصيل الحقوق والمستحقات المحالة ومباشرة حقوق شركة التوريق في مواجهة المدينين لصالح حملة السندات التي تصدرها الشركة بصفته نائبا عنها، فإذا تم الاتفاق على غير ذلك تعين على المحيل إخطار المدنيين الملتزمين بالحقوق والمستحقات والضمانات المحالة بهذا الاتفاق، وذلك بكتاب مسجل مصحوب بعلم الوصول.
وتكون الحوالة في جميع الأحوال نافذة ومنتجة لأثرها دون اشتراط موافقة المدين أو إخطاره بها.
وتتكون محفظة التوريق الصادرة مقابل ما ينشأ عن التدفقات النقدية المستقبلية من بيان معتمد من المحيل يرفق به تقرير لمراقب الحسابات يتضمن صافي القيمة الحالية لمحفظة التدفقات النقدية المستقبلية وأسس تقييمها ، ومعدلات التغيير أو عدم الانتظام بالسداد بها ، والضمانات الإضافية إن وجدت ، ويكون لحملة سندات التوريق حق امتياز علي محفظة التوريق بما يضمن الوفاء بحقوقهم في هذه السندات.
*الفقرة الرابعة مضافة بموجب قانون رقم 13 لسنة 2022.
*مضافة بموجب القانون رقم 143 لسنة 2004$b$, E'\n', E'\r\n')),
    (41, 3, ARRAY['585ff789bc1b6ee85bea9c4a2aa54419']::text[], ARRAY['926435de458a769ceef405128be78e64']::text[], 'd90020bf9f1cfe1c55081020d1549e3e', replace($b$يكون الوفاء بالقيمة الاسمية للسندات التي تصدرها شركة التوريق والعائد عليها من حصيلة محفظة التوريق، ويجوز أن يكون الوفاء مضمونا بضمانات أخرى اتفاقية يتم الوفاء منها بالإضافة إلى تلك الحصيلة.
وتلتزم شركة التوريق بتقديم شهادة بالتصنيف الائتماني لمحفظة التوريق التي تصدر السندات في مقابلها والذي ينبغي ألا تقل درجته عن المستوى الدال على القدرة على الوفاء بالالتزامات، وفقا للقواعد التي يقررها مجلس إدارة الهيئة.
وتلتزم شركة التوريق بإيداع المستندات الدالة على حوالة محفظة التوريق والمبالغ التي يتم تحصيلها بعد خصم مستحقات شركة التوريق ومصاريف عملية التوريق وذلك لحساب حملة السندات لدى أمين للحفظ مرخص له وفقا لأحكام قانون الإيداع والقيد المركزي للأوراق المالية الصادر بالقانون رقم 93 لسنة 2000.
ولأمين الحفظ، بعد موافقة شركة التوريق استثمار المبالغ المودعة لديه، طبقا للشروط والإجراءات التي تحددها اللائحة التنفيذية لهذا القانون.
وتكون المبالغ والمستندات والأوراق المالية والتجارية المودعة لدى أمين الحفظ وفقا لأحكام هذه المادة ملكا لحملة السندات، ولا تدخل في الذمة المالية لشركة التوريق ولا في الضمان العام لدائني المحيل أو الشركة وبخلاف محفظة التوريق لا يحق لحملة سندات التوريق التنفيذ على أصول الشركة.
*مضافة بموجب القانون رقم 143 لسنة 2004$b$, E'\n', E'\r\n')),
    (41, 4, ARRAY['6f71a8cb4a2e858e22a489ba91090ca4']::text[], ARRAY['f8d2393e03cbd0f3f5b3fe8f207526f1']::text[], '163f7a50a73aa2ee1a25e70143654f29', replace($b$على شركة التوريق بذل عناية الشخص الحريص للحفاظ على حقوق حملة السندات كما يلتزم محيل المحفظة بذات العناية متى استمر في تحصيل الحقوق المحالة لحساب شركة التوريق.
*مضافة بموجب القانون رقم 143 لسنة 2004$b$, E'\n', E'\r\n')),
    (41, 5, ARRAY['ad805851cfcc0f5a37074871327b6327']::text[], ARRAY['f6692e184f11bd2d9f9c366a4550ea9e']::text[], 'ad805851cfcc0f5a37074871327b6327', replace($b$تسري على شركة التوريق أحكام المادة (40) من هذا القانون.
*مضافة بموجب القانون رقم 143 لسنة 2004$b$, E'\n', E'\r\n')),
    (41, 6, ARRAY['900c031f57ef271f555e8bfe0155bfac']::text[], ARRAY['bf0d555604473a6554bce1bd540da909']::text[], '15ee545e4f234aa1246c270dd2768546', replace($b$تحدد اللائحة التنفيذية لهذا القانون واجبات شركة التوريق وما يتعين عليها إمساكه من دفاتر وسجلات وذلك فضلا عما هو منصوص عليه في هذا القانون بشأن الشركات العاملة في مجال الأوراق المالية.
*مضافة بموجب القانون رقم 143 لسنة 2004$b$, E'\n', E'\r\n')),
    (41, 7, ARRAY['aa1e6ff61cc275de3afa4cf8eee807c6']::text[], ARRAY['dadac0fc9d891effb6da2fe85e8ab02d']::text[], 'aa1e6ff61cc275de3afa4cf8eee807c6', replace($b$تعفى حوالة محافظ التوريق من ضريبة الدمغة.
مضافة بموجب القانون رقم 143 لسنة 2004$b$, E'\n', E'\r\n')),
    (41, 8, ARRAY['885af8b52310188c208b5bc5b760bdd6']::text[], ARRAY['9b59c5adbe0b8bea3fa66536ecaa189f']::text[], '15a69c27633fd4f8f7cf0386bae0feda', replace($b$على المحيل أن يفصح لشركة التوريق عن المعلومات والبيانات التي تتضمنها محفظة التوريق وذلك دون التقيد بالأحكام المتعلقة بسرية الحسابات المنصوص عليها في قانون البنك المركزي والجهاز المصرفي والنقد الصادر بالقانون رقم 88 لسنة 2003.
*مضافة بموجب القانون رقم 143 لسنة 2004$b$, E'\n', E'\r\n')),
    (41, 9, ARRAY['e4aa131ea9c49342d7a385c222eba2f1']::text[], ARRAY['76ec152b885d0e661ae4ef24ca81f15f']::text[], 'ac16d9df633a77490fe2ee128f263013', replace($b$مع عدم الإخلال بأحكام المادة 12 من هذا القانون للشركات المساهمة من غير شركات التوريق من مجلس إدارة الهيئة إصدار سندات تخصص لسداد قيمتها الاسمية والعائد عليها محفظة مستقلة من الحقوق المالية للشركات بالضمانات المقررة لها.
وفيما عدا حق حملة سندات التوريق في الاشتراك في التنفيذ على حقوق الشركة، تسري على الشركة ومحفظة التوريق المشار إليها الأحكام المنصوص عليها في هذا الفصل.
ويكون ذلك كله وفقا للشروط والإجراءات التي تحددها اللائحة التنفيذية لهذا القانون.
*مضافة بموجب القانون رقم 143 لسنة 2004$b$, E'\n', E'\r\n')),
    (41, 10, ARRAY['f92106963eef31a30ba7b5eb974d3fac']::text[], ARRAY['eb44b85aa7b59d677d5d3055c2f1b5a1']::text[], 'd7774cdb64a3ff80c5b051d75326eb82', replace($b$ينشأ اتحاد يضم الشركات العاملة في مجال الأوراق المالية الخاضعة لأحكام هذا القانون أو لأحكام قانون الإيداع والقيد المركزي للأوراق المالية الصادر بالقانون رقم 93 لسنة 2000 يسمى الاتحاد المصري للأوراق المالية ، يتمتع بالشخصية الاعتبارية المستقلة.
ويختص الاتحاد بتقديم التوصيات في شأن تنمية نشاط سوق رأس المال ، وزيادة الوعى به ، وتبني المبادرات الداعمة للنشاط ، وتقديم التوصيات في شأن التشريعات المنظمة لعمل الجهات المنظمة له ، والعمل على تنمية مهارات العاملين في مجال الأوراق المالية ، والتنسيق بين الأعضاء.
ويصدر بالنظام الأساسي للاتحاد قرار من مجلس إدارة الهيئة ، يتضمن تحديد موارد الاتحاد ، ونسب تمثيل الأنشطة في مجلس إدارته.
ويجب أن يسجل الاتحاد في سجل خاص بالهيئة ، بعد أداء رسم مقداره خمسة آلاف جنيه ، وينشر قرار الإنشاء والنظام الأساسي له في الوقائع المصرية على نفقة الاتحاد.
وتلتزم جميع الشركات المرخص لها بمزاولة أحد أنشطة الشركات العاملة في مجال الأوراق المالية بالانضمام إلى عضوية الاتحاد ومراعاة نظامه الأساسي.
وللاتحاد أن يتخذ ضد أعضائه التدابير الإدارية التي ينص عليها نظامه الأساسي عند مخالفة نظامه أو القواعد المهنية السليمة ، على ألا تكون تلك التدابير مما تختص به الهيئة أو مجلس إدارتها أو رئيسه فوق أحكام هذا القانون.
*مضافة بموجب قانون رقم 17 لسنة 2018.$b$, E'\n', E'\r\n')),
    (42, 0, ARRAY['d61ed30b47f3d50b4efda6983b4bd10d']::text[], ARRAY['0d2f4dda3b56cec2943f7f343a8a5c5e']::text[], '4258eea1c1f8fd29fa1ae7543d834cb4', replace($b$الهيئة العامة للرقابة المالية هيئة عامة تتبع الوزير المختص، مقرها مدينة القاهرة، ويجوز بقرار من الوزير بعد موافقة مجلس إدارة الهيئة إنشاء فروع ومكاتب لها داخل وخارج البلاد.
*معدلة بموجب القانون رقم 10 لسنة 2009 النص قبل التعديل : الهيئة العامة لسوق المال هيئة عامة تتبع وزير الاقتصاد والتجارة الخارجية، مقرها مدينة القاهرة، ويجوز بقرار من الوزير بعد موافقة مجلس إدارة الهيئة إنشاء فروع ومكاتب لها داخل وخارج البلاد.$b$, E'\n', E'\r\n')),
    (43, 0, ARRAY['f178e12c73284a6a4d62afe7d4e680ff']::text[], ARRAY['16359f8290907c3ba69ef3f3342ba8a8']::text[], '1f57deac791d4bfc8d865c259d7dc6bb', replace($b$تتولى الهيئة - فضلا عن الاختصاصات المقررة لها في أي تشريع آخر - تطبيق أحكام هذا القانون والقرارات الصادرة تنفيذا له، ولها إبرام التصرفات واتخاذ الإجراءات اللازمة لتحقيق أغراضها وعلى الأخص:
1. تنظيم وتنمية سوق رأس المال، ويجب أخذ رأي الهيئة في مشروعات القوانين والقرارات المتعلقة بسوق رأس المال.
2. تنظيم أو الإشراف على دورات تدريبية للعاملين في سوق رأس المال أو الراغبين في العمل به.
3. الإشراف على توفير ونشر المعلومات والبيانات الكافية عن سوق رأس المال والتحقق من سلامتها ووضوحها وكشفها عن الحقائق التي تعبر عنها.
4. مراقبة سوق رأس المال للتأكد من أن التعامل يتم على أوراق مالية سليمة، وأنه غير مشوب بالغش أو النصب، أو الاحتيال، أو الاستغلال، أو المضاربات الوهمية.
5. اتخاذ ما يلزم من إجراءات لمتابعة تنفيذ أحكام هذا القانون والقرارات الصادرة تنفيذا له.$b$, E'\n', E'\r\n')),
    (44, 0, ARRAY['e4c2031c0212d231d99c365ad385f753']::text[], ARRAY['abeb30b049ecd8b3999a8d2690d8272c']::text[], '4094d392462d0f51d9604c38e4986026', replace($b$مجلس إدارة الهيئة، هو السلطة المختصة بشئونها وتصريف أمورها، وله أن يتخذ ما يراه لازما من قرارات نهائية لمباشرة اختصاصات الهيئة وتحقيق أغراضها، وعلى الأخص:
1. وضع السياسة التي تسير عليها ممارسة اختصاصاتها وما يتصل بذلك من خطط وبرامج.
2. وضع قواعد التفتيش والرقابة على الشركات الخاضعة لأحكام هذا القانون.
3. تحديد مقابل الخدمات التي تقدمها الهيئة.
4. وضع قواعد الاستعانة بالخبراء وطلب الاستشارات التي تعين الهيئة على قيامها بوظائفها.
5. الموافقة على مشروع الموازنة السنوية للهيئة.
ويكون لمجلس الإدارة بالنسبة إلى الهيئة الاختصاصات المقررة بالقانون رقم 73 لسنة 1976.
ولمجلس الإدارة أن يعهد إلى عضو أو أكثر من بين أعضائه القيام بمهمة محددة.$b$, E'\n', E'\r\n')),
