    (65, 0, ARRAY['52a9a3e8ac82b80cf086859140e98c5e']::text[], ARRAY['80fa1770f0c0cee2516e38c3a585430e']::text[], '433ca5a20035c96dce12dd82959feb55', replace($b$مع عدم الإخلال بأية عقوبة أشد منصوص عليها في أي قانون آخر، يعاقب بالحبس وبغرامة لا تقل عن عشرين ألف جنيه ولا تزيد على مليون جنيه، أو بإحدى هاتين العقوبتين كل من خالف أحكام المواد أرقام (6، 7، 17، 33، 39) والفقرة الثانية من المادة (49) من هذا القانون.
