    (65, 1, ARRAY['aeb3db1129be9604554966369790880d']::text[], ARRAY['aefc14e096cd00c6f8b5cd8c816f1ab4']::text[], '928b4cc96e5ac1c6b4dafdaca0c66291', replace($b$يعاقب بغرامة قدرها ألفا جنيه على كل يوم من أيام التأخير في تسليم القوائم المالية وفقا لقواعد الإفصاح المرتبطة بها والمتعلقة بقواعد قيد وشطب الأوراق المالية المنصوص عليها في المادة 16 من هذا القانون.
ويجوز لرئيس مجلس إدارة الهيئة أو من يفوضه أن يعرض التصالح عن هذه الجريمة في أية حالة كانت عليها الدعوى مقابل أداء نصف الغرامة المستحقة.
ويترتب على التصالح وتنفيذه انقضاء الدعوى الجنائية.
*مضافة موجب القانون رقم 143 لسنة 2004$b$, E'\n', E'\r\n')),
    (66, 0, ARRAY['ff73af9f2004e7ac2f5a9d18820cff03']::text[], ARRAY['c5f04ba4b523b11f0f2a677b875abf52']::text[], 'ad0b0fb322f5bd21bfa7f30d0badb6be', replace($b$يعاقب بغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على مائة ألف جنيه ، كل من تصرف في أوراق مالية أو أدوات مالية على خلاف القواعد المقررة في هذا القانون.
ويعاقب بغرامة لا تقل عن مائة ألف جنيه ولا تزيد على خمسمائة ألف جنيه ، كل من استحوذ على أوراق مالية أو أدوات مالية دون تقديم عرض شراء إجباري في الحالات التي تستوجب ذلك وفقا لأحكام هذا القانون ولائحته التنفيذية.
ويحكم على المخالف في هذه الحالة برد قيمة الأوراق أو الأدوات المالية محل المخالفة ، ولا يجوز التصالح في هذه المخالفة إلا بعد تقديم عرض الشراء الإجباري ، و أداء مقابل للهيئة لا يقل عن (1%) ولا يزيد على (10%) من قيمة الأوراق المالية أو الأدوات المالية محل المخالفة .
*معدلة بموجب قانون رقم 17 لسنة 2018
نص المادة قبل التعديل : يعاقب بغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على عشرة آلاف جنيه، كل من يتصرف في أوراق مالية على خلاف القواعد المقررة في هذا القانون.
ويعاقب بذات العقوبة المنصوص عليها في الفقرة السابقة مدير الشركة الذي يخالف أحكام الفقرة الثانية من المادة (8) من هذا القانون.$b$, E'\n', E'\r\n')),
    (66, 1, ARRAY['3c061fd37fa81afbaecc6bb97f4a325d']::text[], ARRAY['aef4ed63e98b6ef8e6f8a482193ee630']::text[], '83b90914198f580461b651158f9f88d2', replace($b$تسرى العقوبات المنصوص عليها في المواد (63 ، 64 ، الفقرة الأولى من المادة 66 ، 68 ، 69) من هذا القانون على بورصة العقود الآجلة.
