    (69, 1, ARRAY['cb19c2b1c3b601fa6aef2cee347cf61f']::text[], ARRAY['ef27e3a98a1f32f90738f71208aefcca']::text[], 'bd7aa7af6c2f5af0e1bca876b78945ac', replace($b$لا يجوز تحريك الدعوى الجنائية بالنسبة للجرائم المنصوص عليها في هذا القانون إلا بناء على طلب من رئيس الهيئة.
ويجوز لرئيس الهيئة التصالح عن هذه الجرائم في أي حالة كانت عليها الدعوى مقابل أداء مبلغ للهيئة لا يقل عن مثلي الحد الأدنى للغرامة.
ويترتب على التصالح انقضاء الدعوى الجنائية بالنسبة للجريمة التي تم التصالح بشأنها، وتأمر النيابة العامة بوقف تنفيذ العقوبة إذا حصل الصلح أثناء تنفيذها ولو كان الحكم باتا.
*مضافة بموجب القانون رقم 123 لسنة 2008$b$, E'\n', E'\r\n')),
    (70, 0, ARRAY['6c7b3045916b2ef809fe788b8b494ae3']::text[], ARRAY['47cf70ebd9820675a3f5119961475660']::text[], '206511599413c43377c9c81ba15f9bba', replace($b$لكل ذي مصلحة طلب الاطلاع لدى الهيئة على الوثائق والسجلات والمحاضر والتقارير المتعلقة بالشركة والحصول على بيانات أو صور منها مصدق عليها، وذلك مقابل خمسين جنيها على كل وثيقة أو بيان في حالة الاطلاع ومائة جنية عن كل صورة.
*معدلة بموجب القانون رقم 10 لسنة 1995 النص قبل التعديل : لكل ذي مصلحة طلب الاطلاع لدى الهيئة على الوثائق والسجلات والمحاضر والتقارير المتعلقة بالشركة والحصول على بيانات أو صور منها مصدق عليها، وذلك مقابل مائة جنيه عن كل وثيقة أو بيان في حالة الاطلاع ومائتي جنيه عن كل صورة.$b$, E'\n', E'\r\n')),
    (71, 0, ARRAY['9140a8a0c1c9eeabd43bbc6d7c9f3ce5']::text[], ARRAY['ecd02e26b746f578dbf41b520ca058dc']::text[], '43db1d545b96a90e078b381466c6907f', replace($b$يقدم طلب الاطلاع أو الحصول على صور من الوثائق أو البيانات إلى الهيئة مرفقا به ما يفيد دفع المبلغ المقرر على أن يبين في الطلب صفة مقدمه والوثيقة أو البيان الذي يطلب الاطلاع عليه، أو الحصول على صورة منه والغرض المراد استخدامه فيه.
وللهيئة رفض الطلب إذا كان من شأن إذاعة البيانات أو الصور المطلوبة إلحاق ضرر بالشركة أو الإخلال بالمصلحة العامة أو بمصالح المستثمرين.$b$, E'\n', E'\r\n')),
    (72, 0, ARRAY['f64ae94f2405bbf57b5ad4a648faef7f']::text[], ARRAY['1c6dd0ff8e4c80b1860a93137c4add08']::text[], '1b8dcdeeb3b57f71281a31569591a7f4', replace($b$تؤدي الشركة التي يتم تأسيسها طبقا لأحكام هذا القانون إلى الهيئة رسما للتأسيس بواقع واحد في الألف من قيمة رأسمالها المصدر بحد أدنى خمسة آلاف جنيه وبحد أقصى خمسة عشر ألف جنيه، ومقابلا سنويا للخدمات التي تؤديها الهيئة بواقع اثنين في المائة من قيمة رأسمال الشركة المصدر بحد أدنى ألف جنيه وبحد أقصى خمسة آلاف جنيه.$b$, E'\n', E'\r\n')),
    (73, 0, ARRAY['98623166941de482666fff6e30cfbccd']::text[], ARRAY['c576253d1648953b4877e973740136c6']::text[], 'ba26e20169d6cc34d81ca5301888db64', replace($b$تؤدي الشركات التي تصدر أوراقا مالية رسما للهيئة بواقع نصف في الألف من قيمة كل إصدار بحد أقصى عشرة آلاف جنيه.
*معدلة بموجب القانون رقم 10 لسنة 1995
النص قبل التعديل : تؤدى الشركات التي تصدر أوراقا مالية رسما للهيئة بواقع واحد في الألف من قيمة كل إصدار بحد أقصى عشرة آلاف جنيه.$b$, E'\n', E'\r\n')),
    (74, 0, ARRAY['a2e1505e6b6aa031177c697be598a8fb']::text[], ARRAY['e3196952cea5e9bb77e623cd8c8d102a']::text[], 'c319d779595b0cc1da1fcf5a436b07ed', replace($b$يجوز للعاملين في أي شركة من شركات المساهمة أو شركات التوصية بالأسهم تأسيس اتحاد يسمى اتحاد العاملين المساهمين يكون له الشخصية المعنوية، ويتملك لصالحهم بعض أسهم الشركة بموافقة جماعة المؤسسين للشركة أو جمعياتها العامة غير العادية، حسب الأحوال، دون إخلال بحق الاتحاد في شراء الأسهم المقيدة أو المتداولة في بورصة الأوراق المالية.
وتبين اللائحة التنفيذية على الأخص ما يأتي:
1. الشروط الواجب توافرها في الشركات التي يكون للعاملين فيها الحق في إنشاء الاتحاد.
2 .أنواع الأسهم التي يمكن لأعضاء الاتحاد تملكها، وإجراءات تقويمها وأحكام وشروط تداولها، والتنازل عنها وحقوق العاملين بالنسبة لها أثناء مدة خدمتهم وعند انتهاء الخدمة.
3. الشروط الواجب توافرها في الاتحاد واختصاصاته والجهة المختصة بإدارته ووسائل هذه الإدارة.
4. الموارد المالية الذاتية للاتحاد.
ويجوز للاتحاد الحصول على قروض أو منح أو إعانات للغرض الذي أنشئ من أجله.$b$, E'\n', E'\r\n')),
    (75, 0, ARRAY['57cd2f22092c3d2e040e19b119b8d51a']::text[], ARRAY['2155b54e9b2b5f78ca08504184169218']::text[], '4b824ecc13767db4624c0b465be37871', replace($b$يتم إنشاء الاتحاد بقرار من الهيئة العامة للرقابة المالية، ويتم تسجيله وشطبه لدى الهيئة، وفقا للقواعد والأحكام والشروط التي تبينها اللائحة التنفيذية.
ويصدر بنموذج النظام الأساسي للاتحاد قرار من مجلس إدارة الهيئة العامة للرقابة المالية.
*معدلة بموجب القانون رقم 10 لسنة 2009
النص قبل التعديل : يتم إنشاء الاتحاد بقرار من الهيئة العامة لسوق المال، ويتم تسجيله وشطبه لدى الهيئة، وفقا للقواعد والأحكام والشروط التي تبينها اللائحة التنفيذية.
ويصدر بنموذج النظام الأساسي للاتحاد قرار من مجلس إدارة الهيئة العامة لسوق المال.$b$, E'\n', E'\r\n'))
  ) AS t(art_no, suf, old_md5s, old_skels, new_md5, new_body) ORDER BY suf = -1 DESC, art_no, suf
  LOOP
    IF md5(r.new_body) <> r.new_md5 THEN
      RAISE EXCEPTION '[213] نص المادة %/% المحمَّل لا يطابق md5 المختبَر', r.art_no, r.suf;
    END IF;
    v_aid := NULL; v_cur := NULL;
    SELECT a.id, a.body INTO v_aid, v_cur FROM articles a
     WHERE a.law_id = v_law AND a.article_no = r.art_no AND a.article_suffix_order = r.suf;
    IF v_aid IS NULL THEN
      RAISE WARNING '[213] المادة %/% غير موجودة — تخطّى', r.art_no, r.suf;
      v_skip := v_skip + 1; CONTINUE;
    END IF;
    IF md5(v_cur) = r.new_md5 THEN
      v_done := v_done + 1; CONTINUE;
    END IF;
    IF NOT (md5(v_cur) = ANY (r.old_md5s)
            OR md5(regexp_replace(v_cur, '[^ء-ي0-9]|[اأإآلهـ]', '', 'g')) = ANY (r.old_skels)) THEN
      RAISE WARNING '[213] نص المادة %/% الحالى يختلف عن المتوقع (md5 %) — تُخطّيت دون تعديل، راجعها يدوياً', r.art_no, r.suf, md5(v_cur);
      v_skip := v_skip + 1; CONTINUE;
    END IF;

    INSERT INTO migration_213_backup (article_id, version_id, old_body)
      SELECT a.id, NULL, a.body FROM articles a WHERE a.id = v_aid ON CONFLICT DO NOTHING;
    INSERT INTO migration_213_backup (article_id, version_id, old_body)
      SELECT v.article_id, v.id, v.body FROM article_versions v
       WHERE v.article_id = v_aid AND v.body = v_cur ON CONFLICT DO NOTHING;

    UPDATE article_versions SET body = r.new_body WHERE article_id = v_aid AND body = v_cur;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_ok_ver := v_ok_ver + v_n;
    UPDATE articles SET body = r.new_body WHERE id = v_aid AND body = v_cur;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n <> 1 THEN
      RAISE EXCEPTION '[213] عدد المواد المعدلة % بدل 1 (المادة %/%)', v_n, r.art_no, r.suf;
    END IF;
    IF (SELECT md5(body) FROM articles WHERE id = v_aid) <> r.new_md5 THEN
      RAISE EXCEPTION '[213] نص المادة %/% بعد التعديل لا يطابق المختبَر', r.art_no, r.suf;
    END IF;
    v_ok_art := v_ok_art + 1;
  END LOOP;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law) <> 137 THEN
    RAISE EXCEPTION '[213] عدد مواد القانون تغيّر عن 137';
  END IF;
  RAISE NOTICE '[213] قانون 95/1992: مواد معدَّلة % ، نسخ معدَّلة % ، مُصلَحة سابقاً % ، متخطّاة %', v_ok_art, v_ok_ver, v_done, v_skip;
END
$m213$;
